css:
:root {
    --mt-purple: #6f2dbd;
    --mt-purple-dark: #4b1d8f;
    --mt-purple-deep: #2b0c57;
    --mt-lavender: #efe7ff;
    --mt-lavender-2: #f7f2ff;
    --mt-gold: #ffd84d;
    --mt-gold-deep: #f0c62b;
    --mt-white: #ffffff;
    --mt-text: #2d1854;
    --mt-muted: #6d5b8f;
    --mt-border: #e3d6fa;
    --mt-border-strong: #cdb6f5;
    --mt-shadow: 0 1px 2px rgba(43, 12, 87, 0.05), 0 8px 24px rgba(75, 29, 143, 0.08);
    --mt-shadow-strong: 0 14px 35px rgba(43, 12, 87, 0.20);
    --mt-success: #15803d;
    --mt-success-bg: #e8f7ee;
    --mt-warn: #a16207;
    --mt-warn-bg: #fff6d9;
    --mt-danger: #b42318;
    --mt-danger-bg: #fdecea;
    --mt-navbar-offset: calc(var(--np-navbar-height, 60px) + 16px);
}

/* ---------- Page ---------- */

.inventory-dashboard-mt {
    min-height: 100vh;
    background:
        radial-gradient(1200px 400px at 100% -10%, rgba(255, 216, 77, 0.14), transparent 60%),
        radial-gradient(900px 500px at -10% 0%, rgba(111, 45, 189, 0.08), transparent 60%),
        linear-gradient(180deg, #fbf8ff 0%, #f3ecfd 100%);
    color: var(--mt-text);
    font-variant-numeric: tabular-nums;
}

.inventory-dashboard-mt .text-end {
    text-align: right;
}

.mt-shell {
    max-width: 1760px;
    margin: 0 auto;
    padding: 24px 24px 96px;
}

.dashboard-card {
    background: var(--mt-white);
    border: 1px solid var(--mt-border);
    border-radius: 18px;
    box-shadow: var(--mt-shadow);
}

/* ---------- Top bar ---------- */

.mt-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
    margin-bottom: 22px;
}

.mt-brand {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
}

.mt-brand-mark {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    flex: none;
    border-radius: 14px;
    background: linear-gradient(135deg, var(--mt-purple) 0%, var(--mt-purple-deep) 100%);
    color: var(--mt-gold);
    box-shadow: 0 10px 22px rgba(75, 29, 143, 0.28);
}

.dashboard-title {
    margin: 0;
    font-size: 28px;
    font-weight: 900;
    letter-spacing: -0.5px;
    color: var(--mt-purple-deep);
}

.dashboard-subtitle {
    font-size: 14px;
    color: var(--mt-muted);
}

/* ---------- Layout ---------- */

.mt-layout {
    display: grid;
    grid-template-columns: 280px minmax(0, 1fr);
    gap: 22px;
    align-items: start;
}

.mt-main {
    min-width: 0;
}

/* ---------- Sidebar ---------- */

.sidebar-card {
    position: sticky;
    top: var(--mt-navbar-offset);
    overflow: hidden;
}

.sidebar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 18px;
    background: linear-gradient(135deg, var(--mt-purple-deep) 0%, var(--mt-purple) 100%);
    color: var(--mt-white);
}

.sidebar-title {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    font-weight: 900;
    letter-spacing: 0.2px;
}

.sidebar-title svg {
    color: var(--mt-gold);
}

.toggle-icon {
    display: none;
    font-size: 12px;
}

.sidebar-body {
    padding: 12px;
    max-height: calc(100vh - var(--mt-navbar-offset) - 80px);
    overflow-y: auto;
}

.sidebar-body.collapsed {
    display: none;
}

.group-search-wrap {
    position: relative;
    margin-bottom: 10px;
}

.group-search-wrap svg {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--mt-muted);
    pointer-events: none;
}

.group-search {
    width: 100%;
    height: 38px;
    padding: 0 12px 0 34px;
    border: 1px solid var(--mt-border);
    border-radius: 10px;
    background: var(--mt-lavender-2);
    color: var(--mt-text);
    font-size: 13px;
    outline: none;
}

.group-search:focus {
    border-color: var(--mt-purple);
    background: var(--mt-white);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.15);
}

.group-list-container {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.item-group-btn {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    width: 100%;
    padding: 10px 12px 10px 14px;
    border: 1px solid transparent;
    border-radius: 10px;
    background: transparent;
    color: var(--mt-text);
    font-size: 14px;
    font-weight: 700;
    text-align: left;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease;
}

.item-group-btn[hidden] {
    display: none;
}

.item-group-btn:hover {
    background: var(--mt-lavender-2);
    color: var(--mt-purple);
}

.item-group-btn:focus-visible {
    outline: none;
    border-color: var(--mt-purple);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.15);
}

.ig-chevron {
    flex: none;
    opacity: 0;
    color: var(--mt-purple);
    transition: opacity 0.15s ease, transform 0.15s ease;
}

.item-group-btn:hover .ig-chevron {
    opacity: 0.6;
}

.item-group-btn.active {
    background: var(--mt-lavender);
    color: var(--mt-purple-deep);
    font-weight: 900;
}

.item-group-btn.active::before {
    content: "";
    position: absolute;
    left: 0;
    top: 8px;
    bottom: 8px;
    width: 4px;
    border-radius: 0 4px 4px 0;
    background: var(--mt-purple);
}

.item-group-btn.active .ig-chevron {
    opacity: 1;
    transform: translateX(2px);
}

.group-empty {
    padding: 14px 8px;
    text-align: center;
    font-size: 13px;
    color: var(--mt-muted);
}

.group-empty[hidden] {
    display: none;
}

/* ---------- Group heading ---------- */

.selected-group-wrap {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 16px;
}

.mt-eyebrow {
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: var(--mt-purple);
}

.selected-group-text {
    margin: 2px 0 0;
    font-size: 24px;
    font-weight: 900;
    letter-spacing: -0.3px;
    color: var(--mt-purple-deep);
}

.selected-group-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

/* ---------- Buttons ---------- */

.mt-export-btn,
.mt-reset-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 40px;
    padding: 0 16px;
    border-radius: 12px;
    font-weight: 800;
    font-size: 14px;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.mt-export-btn {
    border: 1px solid var(--mt-gold-deep);
    background: linear-gradient(135deg, #fff8dd 0%, var(--mt-gold) 100%);
    color: var(--mt-purple-deep);
}

.mt-export-btn:hover,
.mt-export-btn:focus-visible {
    background: var(--mt-gold-deep);
    color: var(--mt-purple-deep);
}

.mt-reset-btn {
    border: 1px solid var(--mt-border);
    background: var(--mt-white);
    color: var(--mt-purple-dark);
}

.mt-reset-btn:hover,
.mt-reset-btn:focus-visible {
    border-color: var(--mt-purple);
    background: var(--mt-lavender-2);
    color: var(--mt-purple);
}

/* ---------- Summary ---------- */

.summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
    margin-bottom: 16px;
}

.summary-card {
    position: relative;
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 18px;
    overflow: hidden;
}

.summary-card::after {
    content: "";
    position: absolute;
    right: -30px;
    top: -30px;
    width: 110px;
    height: 110px;
    border-radius: 50%;
    background: currentColor;
    opacity: 0.05;
    pointer-events: none;
}

.summary-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    flex: none;
    border-radius: 12px;
}

.summary-text {
    min-width: 0;
}

.summary-label {
    margin-bottom: 2px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.4px;
    text-transform: uppercase;
    color: var(--mt-muted);
}

.summary-value {
    font-size: 26px;
    font-weight: 900;
    line-height: 1.15;
    color: var(--mt-purple-deep);
    overflow-wrap: anywhere;
}

.summary-1 { color: var(--mt-purple); }
.summary-1 .summary-icon { background: var(--mt-lavender); color: var(--mt-purple); }

.summary-2 { color: #4f46e5; }
.summary-2 .summary-icon { background: #eef0ff; color: #4f46e5; }

.summary-3 { color: var(--mt-success); }
.summary-3 .summary-icon { background: var(--mt-success-bg); color: var(--mt-success); }

.summary-4 { color: var(--mt-warn); }
.summary-4 .summary-icon { background: var(--mt-warn-bg); color: var(--mt-warn); }

/* ---------- Filters ---------- */

.filter-card {
    margin-bottom: 16px;
}

.filter-bar {
    display: flex;
    align-items: flex-end;
    flex-wrap: wrap;
    gap: 12px 14px;
    padding: 14px 16px;
}

.filter-field {
    display: flex;
    flex-direction: column;
    gap: 4px;
    flex: 1 1 170px;
    min-width: 0;
}

.filter-field.filter-search {
    flex: 2 1 240px;
}

.filter-label {
    margin: 0;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: var(--mt-muted);
}

.inventory-dashboard-mt .form-control {
    height: 40px;
    border: 1px solid var(--mt-border);
    border-radius: 10px;
    background: var(--mt-white);
    color: var(--mt-text);
    font-size: 14px;
    box-shadow: none;
}

.inventory-dashboard-mt .form-control:focus {
    border-color: var(--mt-purple);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.15);
}

.input-icon {
    position: relative;
}

.input-icon svg {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--mt-muted);
    pointer-events: none;
}

.input-icon .form-control {
    padding-left: 34px;
}

.filter-toggles {
    display: flex;
    align-items: center;
    gap: 16px;
    height: 40px;
}

.mt-switch {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    cursor: pointer;
    user-select: none;
}

.mt-switch input {
    position: absolute;
    opacity: 0;
    width: 1px;
    height: 1px;
}

.mt-switch-track {
    position: relative;
    width: 38px;
    height: 22px;
    flex: none;
    border-radius: 999px;
    background: #d9cdee;
    transition: background 0.15s ease;
}

.mt-switch-track::after {
    content: "";
    position: absolute;
    top: 3px;
    left: 3px;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--mt-white);
    box-shadow: 0 1px 3px rgba(43, 12, 87, 0.3);
    transition: transform 0.15s ease;
}

.mt-switch input:checked + .mt-switch-track {
    background: var(--mt-purple);
}

.mt-switch input:checked + .mt-switch-track::after {
    transform: translateX(16px);
}

.mt-switch input:focus-visible + .mt-switch-track {
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.25);
}

.mt-switch-label {
    font-size: 13px;
    font-weight: 700;
    color: var(--mt-text);
    white-space: nowrap;
}

/* ---------- Table ---------- */

.table-card {
    overflow: hidden;
}

.table-wrapper {
    max-height: calc(100vh - var(--mt-navbar-offset) - 24px);
    overflow: auto;
    background: var(--mt-white);
}

.stock-table {
    width: 100%;
    min-width: 980px;
    margin: 0;
    border: 0;
    border-collapse: separate;
    border-spacing: 0;
}

.stock-table thead th {
    position: sticky;
    top: 0;
    z-index: 2;
    padding: 12px 14px;
    background: #f6f1ff;
    color: var(--mt-purple-dark);
    border: 0;
    border-bottom: 1px solid var(--mt-border-strong);
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    white-space: nowrap;
    vertical-align: middle;
}

.stock-table tbody td {
    padding: 11px 14px;
    border: 0;
    border-bottom: 1px solid #f1eafc;
    font-size: 13px;
    vertical-align: middle;
    background: var(--mt-white);
    transition: background 0.12s ease;
}

.stock-table tbody tr:last-child td {
    border-bottom: 0;
}

.stock-table tbody tr:hover td {
    background: #fbf8ff;
}

.stock-table td.num {
    white-space: nowrap;
}

.stock-table tr.row-warning td {
    background: #fffcf2;
}

.stock-table tr.row-danger td {
    background: #fff7f8;
    color: #7a6a8f;
}

.stock-table tr.row-danger .item-name {
    color: #7a6a8f;
}

.item-code-cell {
    display: flex;
    align-items: center;
    gap: 6px;
    white-space: nowrap;
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 12px;
    color: var(--mt-muted);
}

.item-name {
    font-weight: 800;
    color: var(--mt-purple-deep);
}

.copy-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    border: 1px solid transparent;
    border-radius: 8px;
    background: transparent;
    color: var(--mt-muted);
    cursor: pointer;
    opacity: 0.45;
    transition: opacity 0.15s ease, background 0.15s ease;
}

.stock-table tr:hover .copy-btn,
.copy-btn:focus-visible {
    opacity: 1;
}

.copy-btn:hover {
    background: var(--mt-lavender);
    color: var(--mt-purple);
}

/* Badges */
.status-badge,
.type-badge,
.yield-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 800;
    white-space: nowrap;
}

.status-badge::before {
    content: "";
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: currentColor;
}

.status-good {
    background: var(--mt-success-bg);
    color: var(--mt-success);
}

.status-low {
    background: var(--mt-warn-bg);
    color: var(--mt-warn);
}

.status-out {
    background: var(--mt-danger-bg);
    color: var(--mt-danger);
}

.type-bho {
    background: var(--mt-lavender);
    color: #5a2396;
}

.type-sho {
    background: #fff4c4;
    color: #7b5600;
}

.yield-badge {
    background: #f4f0ff;
    color: var(--mt-purple-dark);
}

.yield-legend {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 16px;
    margin: 0 0 14px;
    padding: 10px 14px;
    border: 1px solid #e6dcf7;
    border-radius: 12px;
    background: #fff;
    font-size: 12px;
}

.yield-legend[hidden] {
    display: none;
}

.yield-legend-title {
    font-weight: 800;
    color: var(--mt-purple-dark);
}

.yield-legend-item {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--mt-text, #1f2937);
}

.yield-legend-swatch {
    width: 14px;
    height: 14px;
    border-radius: 4px;
    flex: 0 0 auto;
}

.yield-legend-none {
    color: var(--mt-muted);
    font-style: italic;
}

.yield-badges {
    display: inline-flex;
    flex-wrap: wrap;
    gap: 4px;
}

.yield-badge-customer {
    border: 1px solid;
    cursor: help;
}

.yield-badge-rosin {
    background: #fff8e6;
    color: #7b5600;
}

.grade-badge {
    display: inline-block;
    padding: 3px 8px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 800;
    white-space: nowrap;
}

.grade-t1 {
    background: #f2c230;
    color: #4a3200;
}

.grade-t2 {
    background: #5c3317;
    color: #ffffff;
}

.grade-t3 {
    background: #111111;
    color: #ffffff;
}

.grade-badge.grade-zero {
    opacity: 0.45;
}

/* States */
.empty-state,
.loading-state {
    padding: 56px 16px;
    text-align: center;
    color: var(--mt-muted);
    font-weight: 700;
}

.loading-state::before {
    content: "";
    display: block;
    width: 28px;
    height: 28px;
    margin: 0 auto 12px;
    border: 3px solid var(--mt-lavender);
    border-top-color: var(--mt-purple);
    border-radius: 50%;
    animation: mt-spin 0.8s linear infinite;
}

@keyframes mt-spin {
    to { transform: rotate(360deg); }
}

/* ---------- Responsive ---------- */

@media (max-width: 1199px) {
    .mt-layout {
        grid-template-columns: 1fr;
    }

    .sidebar-card {
        position: static;
    }

    .sidebar-header {
        cursor: pointer;
    }

    .toggle-icon {
        display: inline;
    }

    .sidebar-body {
        max-height: none;
    }

    .group-list-container {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
    }

    .summary-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 767px) {
    .mt-shell {
        padding: 16px 16px 96px;
    }

    .dashboard-title {
        font-size: 22px;
    }

    .mt-brand-mark {
        width: 40px;
        height: 40px;
    }

    .selected-group-text {
        font-size: 20px;
    }

    .summary-card {
        padding: 14px;
    }

    .summary-icon {
        width: 36px;
        height: 36px;
    }

    .summary-value {
        font-size: 20px;
    }

    .filter-toggles {
        height: auto;
        flex-wrap: wrap;
    }

    .mt-reset-btn {
        flex: 1 1 100%;
    }

    .table-wrapper {
        max-height: 70vh;
    }
}

@media (prefers-reduced-motion: reduce) {
    .loading-state::before {
        animation-duration: 2s;
    }
}

/* ---------- Order cart ---------- */

.header-right {
    display: flex;
    align-items: center;
    gap: 10px;
}

.mt-order-btn[hidden],
.mt-order-float[hidden],
.mt-modal-backdrop[hidden],
.mt-modal-content[hidden],
.mt-modal-footer[hidden],
.mt-modal-success[hidden],
.of-field[hidden],
.order-banner[hidden],
.order-error[hidden],
.ol-warn[hidden] {
    display: none !important;
}

/* Header button */
.mt-order-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: 0;
    border-radius: 999px;
    padding: 10px 16px 10px 18px;
    font-weight: 800;
    background: linear-gradient(135deg, var(--mt-purple) 0%, var(--mt-purple-dark) 100%);
    color: var(--mt-white);
    box-shadow: var(--mt-shadow-strong);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.mt-order-btn:hover,
.mt-order-btn:focus-visible {
    color: var(--mt-gold);
    transform: translateY(-1px);
}

.order-count-badge {
    min-width: 26px;
    padding: 2px 8px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.18);
    color: var(--mt-white);
    font-size: 12px;
    text-align: center;
}

.mt-reserve-btn {
    background: var(--mt-white);
    color: var(--mt-purple-dark);
    border: 1px solid var(--mt-border-strong);
}

.mt-reserve-btn:hover,
.mt-reserve-btn:focus-visible {
    color: var(--mt-purple);
    background: var(--mt-lavender-2);
}

.mt-order-btn.has-items .order-count-badge {
    background: var(--mt-gold);
    color: var(--mt-purple-deep);
}

/* Row checkboxes */
.order-check-col {
    width: 44px;
    text-align: center;
    vertical-align: middle;
}

.order-check {
    width: 18px;
    height: 18px;
    cursor: pointer;
    accent-color: var(--mt-purple);
    vertical-align: middle;
}

.stock-table tr.row-selected td {
    background: var(--mt-lavender) !important;
}

.stock-table tr.row-selected td:first-child {
    box-shadow: inset 4px 0 0 var(--mt-purple);
}

/* Floating "View Order" bar */
.mt-order-float {
    position: fixed;
    right: 24px;
    bottom: 24px;
    z-index: 1045;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    max-width: calc(100vw - 32px);
    padding: 10px 10px 10px 16px;
    border: 0;
    border-radius: 999px;
    background: var(--mt-purple-deep);
    color: var(--mt-white);
    font-weight: 800;
    box-shadow: 0 18px 40px rgba(43, 12, 87, 0.35);
    cursor: pointer;
    animation: mt-rise 0.2s ease-out;
}

.mt-order-float-icon {
    display: inline-flex;
    color: var(--mt-gold);
}

.mt-order-float-cta {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 999px;
    background: var(--mt-gold);
    color: var(--mt-purple-deep);
}

.mt-order-float:hover .mt-order-float-cta {
    background: var(--mt-gold-deep);
}

/* Modal shell */
body.mt-modal-open {
    overflow: hidden;
}

/* Error dialogs (frappe.msgprint), the save freeze and toasts must still show
   on top of the popup while it is open. */
body.mt-modal-open .modal {
    z-index: 1080 !important;
}

body.mt-modal-open .modal-backdrop {
    z-index: 1070 !important;
}

body.mt-modal-open #alert-container {
    z-index: 1090 !important;
}

.mt-modal-backdrop {
    position: fixed;
    inset: 0;
    /* Above the theme's navbar (z-index 1050 !important). */
    z-index: 1060;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px 16px;
    background: rgba(43, 12, 87, 0.5);
    backdrop-filter: blur(3px);
    animation: mt-fade 0.15s ease-out;
}

.mt-modal {
    display: flex;
    flex-direction: column;
    width: 100%;
    max-width: 1120px;
    max-height: calc(100vh - 48px);
    background: #fcfaff;
    color: var(--mt-text);
    border-radius: 22px;
    box-shadow: 0 30px 70px rgba(43, 12, 87, 0.35);
    overflow: hidden;
    animation: mt-pop 0.18s ease-out;
}

.mt-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 18px 22px;
    background: linear-gradient(135deg, var(--mt-purple-deep) 0%, var(--mt-purple) 100%);
    color: var(--mt-white);
}

.mt-modal-heading {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.mt-modal-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 12px;
    background: rgba(255, 216, 77, 0.16);
    color: var(--mt-gold);
    flex: none;
}

.mt-modal-header h4 {
    margin: 0;
    font-size: 20px;
    font-weight: 900;
    color: var(--mt-white);
}

.mt-modal-sub {
    font-size: 13px;
    color: rgba(255, 255, 255, 0.75);
}

.mt-modal-header-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

.mt-draft-pill {
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.25);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.3px;
    text-transform: uppercase;
}

.mt-modal-close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: var(--mt-white);
    cursor: pointer;
}

.mt-modal-close:hover,
.mt-modal-close:focus-visible {
    background: rgba(255, 255, 255, 0.14);
}

.mt-modal-content {
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
    flex: 1;
    min-height: 0;
    overflow: hidden;
}

.order-pane {
    min-height: 0;
    overflow-y: auto;
    padding: 18px 22px 22px;
}

.order-pane-details {
    background: var(--mt-white);
    border-left: 1px solid var(--mt-border);
}

.order-pane-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
}

.order-pane-head h5 {
    margin: 0;
    font-size: 15px;
    font-weight: 900;
    color: var(--mt-purple-dark);
}

.mt-link-btn {
    border: 0;
    background: none;
    padding: 4px 6px;
    font-size: 13px;
    font-weight: 800;
    color: #b42318;
    cursor: pointer;
    border-radius: 8px;
}

.mt-link-btn:hover,
.mt-link-btn:focus-visible {
    background: #fdecea;
}

/* Info banner */
.order-banner {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    margin-bottom: 12px;
    padding: 10px 12px;
    border-radius: 12px;
    background: #fff8dd;
    border: 1px solid var(--mt-gold-deep);
    color: var(--mt-purple-deep);
    font-size: 13px;
}

.order-banner svg {
    flex: none;
    margin-top: 1px;
    color: #a16207;
}

/* Item cards */
.order-lines {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.ol-card {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 6px 14px;
    padding: 12px 14px;
    border: 1px solid var(--mt-border);
    border-radius: 14px;
    background: var(--mt-white);
    box-shadow: 0 4px 12px rgba(111, 45, 189, 0.05);
}

.ol-card.is-over {
    border-color: #f0b44c;
    background: #fffaf0;
}

.ol-name {
    font-weight: 800;
    font-size: 15px;
    color: var(--mt-purple-deep);
    overflow-wrap: anywhere;
}

.ol-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    margin-top: 3px;
}

.ol-code {
    font-size: 12px;
    color: var(--mt-muted);
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.ol-chip {
    padding: 1px 8px;
    border-radius: 999px;
    background: var(--mt-lavender);
    color: var(--mt-purple-dark);
    font-size: 11px;
    font-weight: 800;
}

.ol-stock {
    margin-top: 4px;
    font-size: 12px;
    color: var(--mt-muted);
}

.ol-stock strong {
    color: var(--mt-text);
}

.ol-inputs {
    display: flex;
    align-items: flex-end;
    gap: 8px;
}

.ol-input {
    display: flex;
    flex-direction: column;
    gap: 3px;
    margin: 0;
}

.ol-input span {
    font-size: 11px;
    font-weight: 800;
    color: var(--mt-muted);
    text-transform: uppercase;
    letter-spacing: 0.3px;
}

.ol-input .form-control {
    width: 104px;
    height: 38px;
    text-align: right;
    font-weight: 700;
    border-radius: 10px;
}

.ol-remove {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    border: 1px solid transparent;
    border-radius: 10px;
    background: transparent;
    color: #b42318;
    cursor: pointer;
}

.ol-remove:hover,
.ol-remove:focus-visible {
    background: #fdecea;
    border-color: #f5b5ad;
}

.ol-warn {
    grid-column: 1 / -1;
    font-size: 12px;
    font-weight: 700;
    color: #a16207;
}

.order-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 36px 16px;
    border: 2px dashed var(--mt-border);
    border-radius: 16px;
    text-align: center;
    color: var(--mt-muted);
}

.order-empty-icon {
    color: var(--mt-purple);
    opacity: 0.6;
}

.order-empty strong {
    color: var(--mt-purple-dark);
}

/* Details form */
.of-group + .of-group {
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px dashed var(--mt-border);
}

.of-group-title {
    margin-bottom: 8px;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.6px;
    text-transform: uppercase;
    color: var(--mt-purple);
}

.of-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px 12px;
}

.of-field.of-wide {
    grid-column: 1 / -1;
}

.of-field label {
    display: block;
    margin-bottom: 4px;
    font-size: 12px;
    font-weight: 800;
    color: var(--mt-muted);
}

.of-control {
    border-radius: 10px;
    border-color: var(--mt-border);
    min-height: 40px;
}

.of-control:focus,
.ol-input .form-control:focus {
    border-color: var(--mt-purple);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.18);
}

.of-control.is-invalid,
.ol-input .form-control.is-invalid {
    border-color: #d92d20;
    box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.15);
}

.of-reqd {
    color: #b42318;
}

/* Footer */
.mt-modal-footer {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
    padding: 14px 22px;
    border-top: 1px solid var(--mt-border);
    background: var(--mt-white);
}

.mt-modal-hint {
    font-size: 12px;
    color: var(--mt-muted);
}

.mt-modal-spacer {
    flex: 1;
}

.mt-cancel-btn {
    border-radius: 12px;
    font-weight: 800;
    padding: 10px 16px;
    background: var(--mt-white);
    border: 1px solid var(--mt-border);
    color: var(--mt-purple-dark);
}

.mt-cancel-btn:hover {
    background: var(--mt-lavender-2);
    color: var(--mt-purple-dark);
}

.mt-save-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: 0;
    border-radius: 12px;
    font-weight: 900;
    padding: 10px 18px;
    background: linear-gradient(135deg, var(--mt-purple) 0%, var(--mt-purple-dark) 100%);
    color: var(--mt-gold);
    box-shadow: 0 8px 18px rgba(75, 29, 143, 0.25);
}

.mt-save-btn:hover,
.mt-save-btn:focus-visible {
    color: var(--mt-white);
}

.mt-save-btn:disabled {
    opacity: 0.6;
}

.order-error {
    flex-basis: 100%;
    padding: 10px 12px;
    border-radius: 12px;
    background: #fdecea;
    border: 1px solid #f5b5ad;
    color: #8a1c12;
    font-weight: 700;
}

/* Success view */
.mt-modal-success {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 36px 22px 30px;
    text-align: center;
    overflow-y: auto;
}

.order-success-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 72px;
    height: 72px;
    border-radius: 50%;
    background: #e8f7ee;
    color: #15803d;
    box-shadow: 0 0 0 8px #f3fbf6;
    margin-bottom: 14px;
    animation: mt-pop 0.25s ease-out;
}

.mt-modal-success h4 {
    margin: 0 0 4px;
    font-weight: 900;
    color: var(--mt-purple-deep);
}

.mt-modal-success p {
    margin: 0 0 18px;
    color: var(--mt-muted);
}

.order-success-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
    width: 100%;
    max-width: 480px;
}

.order-success-card {
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-areas: "name open" "meta open";
    gap: 2px 12px;
    align-items: center;
    padding: 12px 16px;
    border: 1px solid var(--mt-border);
    border-radius: 14px;
    background: var(--mt-white);
    text-align: left;
    text-decoration: none !important;
    transition: border-color 0.15s ease, transform 0.15s ease;
}

.order-success-card:hover,
.order-success-card:focus-visible {
    border-color: var(--mt-purple);
    transform: translateY(-1px);
}

.order-success-name {
    grid-area: name;
    font-weight: 900;
    color: var(--mt-purple-dark);
}

.order-success-meta {
    grid-area: meta;
    font-size: 12px;
    color: var(--mt-muted);
}

.order-success-open {
    grid-area: open;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 800;
    color: var(--mt-purple);
}

.order-success-actions {
    display: flex;
    gap: 10px;
    margin-top: 22px;
}

@keyframes mt-fade {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes mt-pop {
    from { opacity: 0; transform: translateY(8px) scale(0.98); }
    to { opacity: 1; transform: none; }
}

@keyframes mt-rise {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
    .mt-modal,
    .mt-modal-backdrop,
    .mt-order-float,
    .order-success-badge {
        animation: none;
    }
}

@media (max-width: 900px) {
    .mt-modal-content {
        grid-template-columns: 1fr;
        overflow-y: auto;
    }

    .order-pane {
        overflow: visible;
    }

    .order-pane-details {
        border-left: 0;
        border-top: 1px solid var(--mt-border);
    }
}

@media (max-width: 640px) {
    .mt-modal-backdrop {
        padding: 0;
        align-items: stretch;
    }

    .mt-modal {
        max-height: none;
        height: 100%;
        border-radius: 0;
    }

    .mt-modal-header,
    .order-pane,
    .mt-modal-footer {
        padding-left: 16px;
        padding-right: 16px;
    }

    .mt-draft-pill,
    .mt-modal-hint {
        display: none;
    }

    .ol-card {
        grid-template-columns: 1fr;
    }

    .ol-inputs {
        justify-content: flex-start;
    }

    .ol-input .form-control {
        width: 96px;
    }

    .of-grid {
        grid-template-columns: 1fr;
    }

    .header-right,
    .mt-order-btn {
        width: 100%;
        justify-content: center;
    }

    .mt-order-float {
        right: 16px;
        bottom: 16px;
        left: 16px;
        justify-content: space-between;
    }

    .mt-modal-footer .btn {
        flex: 1;
        justify-content: center;
    }
}

/* ---------- Access code lock ---------- */

.mt-modal {
    position: relative;
}

.mt-modal.is-locked > :not(.order-lock) {
    filter: blur(6px);
    pointer-events: none;
    user-select: none;
}

.order-lock[hidden],
.order-lock-error[hidden],
.order-totals[hidden] {
    display: none !important;
}

.order-lock {
    position: absolute;
    inset: 0;
    z-index: 5;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px 16px;
    background: rgba(247, 242, 255, 0.55);
}

.order-lock-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    max-width: 360px;
    padding: 28px 24px 22px;
    border: 1px solid var(--mt-border);
    border-radius: 20px;
    background: var(--mt-white);
    box-shadow: 0 24px 60px rgba(43, 12, 87, 0.28);
    text-align: center;
    animation: mt-pop 0.18s ease-out;
}

.order-lock-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    margin-bottom: 12px;
    border-radius: 16px;
    background: linear-gradient(135deg, var(--mt-purple) 0%, var(--mt-purple-deep) 100%);
    color: var(--mt-gold);
}

.order-lock-card h5 {
    margin: 0 0 4px;
    font-weight: 900;
    color: var(--mt-purple-deep);
}

.order-lock-card p {
    margin: 0 0 16px;
    font-size: 13px;
    color: var(--mt-muted);
}

.order-lock-input {
    height: 48px;
    border-radius: 12px;
    border-color: var(--mt-border);
    text-align: center;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: 6px;
}

.order-lock-input:focus {
    border-color: var(--mt-purple);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.18);
}

.order-lock-error {
    width: 100%;
    margin-top: 10px;
    padding: 8px 10px;
    border-radius: 10px;
    background: var(--mt-danger-bg);
    color: var(--mt-danger);
    font-size: 13px;
    font-weight: 700;
}

.order-lock-actions {
    display: flex;
    gap: 10px;
    width: 100%;
    margin-top: 16px;
}

.order-lock-actions .btn {
    flex: 1;
    justify-content: center;
}

.order-lock-card.shake {
    animation: mt-shake 0.35s ease-in-out;
}

@keyframes mt-shake {
    0%, 100% { transform: translateX(0); }
    20% { transform: translateX(-8px); }
    40% { transform: translateX(8px); }
    60% { transform: translateX(-5px); }
    80% { transform: translateX(5px); }
}

/* ---------- Rate currency, line subtotal, totals ---------- */

.ol-money {
    position: relative;
    display: block;
}

.ol-currency {
    position: absolute;
    left: 10px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 13px;
    font-weight: 800;
    color: var(--mt-muted);
    pointer-events: none;
}

.ol-money .form-control.ol-rate {
    width: 120px;
    padding-left: 24px;
}

.ol-subtotal {
    grid-column: 1 / -1;
    padding-top: 8px;
    border-top: 1px dashed var(--mt-border);
    text-align: right;
    font-size: 13px;
    color: var(--mt-muted);
}

.ol-subtotal strong {
    margin-left: 6px;
    font-size: 15px;
    color: var(--mt-purple-deep);
}

.order-totals {
    position: sticky;
    bottom: 0;
    margin: 14px -22px -22px;
    padding: 14px 22px 16px;
    border-top: 1px solid var(--mt-border);
    background: linear-gradient(180deg, rgba(252, 250, 255, 0.92) 0%, #f7f2ff 100%);
    backdrop-filter: blur(4px);
}

.ot-row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    padding: 3px 0;
    font-size: 14px;
    color: var(--mt-muted);
}

.ot-row strong {
    color: var(--mt-text);
    font-weight: 800;
}

.ot-row.ot-total {
    margin-top: 6px;
    padding-top: 8px;
    border-top: 1px solid var(--mt-border);
    font-size: 16px;
    font-weight: 900;
    color: var(--mt-purple-deep);
}

.ot-row.ot-total strong {
    font-size: 20px;
    color: var(--mt-purple-deep);
}

.ot-note {
    margin-top: 6px;
    font-size: 12px;
    color: var(--mt-muted);
}

.warehouse-cell {
    white-space: nowrap;
}

@media (max-width: 900px) {
    .order-totals {
        position: static;
        margin: 14px 0 0;
        padding: 14px 0 0;
        background: none;
        backdrop-filter: none;
    }
}

@media (prefers-reduced-motion: reduce) {
    .order-lock-card,
    .order-lock-card.shake {
        animation: none;
    }
}

/* Click-to-sort column headers */
.stock-table thead th.sortable-th {
    cursor: pointer;
    user-select: none;
}

.stock-table thead th.sortable-th:hover {
    background: var(--mt-lavender);
}

.stock-table thead th .sort-arrow {
    margin-left: 5px;
    font-size: 10px;
    opacity: 0.35;
}

.stock-table thead th.sorted .sort-arrow {
    opacity: 1;
    color: var(--mt-purple);
}

/* Clone / Seed */
.prop-badge {
    display: inline-block;
    padding: 3px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 800;
    white-space: nowrap;
}

.prop-clone {
    background: var(--mt-success-bg);
    color: var(--mt-success);
}

.prop-seed {
    background: var(--mt-warn-bg);
    color: var(--mt-warn);
}

.breeder-cell {
    white-space: nowrap;
}

/* Warehouse multi-select */
.wh-multi {
    position: relative;
}

.inventory-dashboard-mt .wh-multi-btn {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    width: 100%;
    padding: 0 12px;
    text-align: left;
    cursor: pointer;
}

.wh-multi-label {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.wh-multi-btn svg {
    flex: none;
    color: var(--mt-muted);
}

.wh-multi-menu {
    position: absolute;
    top: calc(100% + 4px);
    left: 0;
    z-index: 20;
    min-width: 100%;
    max-height: 320px;
    overflow-y: auto;
    padding: 6px;
    background: var(--mt-white);
    border: 1px solid var(--mt-border);
    border-radius: 10px;
    box-shadow: var(--mt-shadow-strong);
}

.wh-multi-menu[hidden] {
    display: none;
}

.wh-multi-option {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    padding: 7px 8px;
    border-radius: 7px;
    font-size: 13px;
    color: var(--mt-text);
    white-space: nowrap;
    cursor: pointer;
}

.wh-multi-option:hover {
    background: var(--mt-lavender-2);
}

.wh-multi-option input {
    accent-color: var(--mt-purple);
    margin: 0;
}

.wh-multi-all {
    font-weight: 800;
    border-bottom: 1px solid var(--mt-border);
    border-radius: 7px 7px 0 0;
    margin-bottom: 4px;
}

/* Reserved sales orders popup */
.mt-reserve-modal {
    max-width: 1000px;
}

.reserve-toolbar {
    padding: 14px 22px;
    border-bottom: 1px solid var(--mt-border);
    background: var(--mt-white);
}

.reserve-body {
    flex: 1;
    min-height: 0;
