javascript:
frappe.ready(function () {
    bindGlobalFilters();
    bindSidebarToggle();
    bindExportButton();
    bindTableSort();
    bindGroupSearch();
    initOrderCart();
    initReserveView();
    initAddYield();
    initNotes();
    loadItemGroups();
});

// ---------------------------------------------------
// CONFIG
// ---------------------------------------------------

const GROUP_ORDER = [
    'Fresh Frozen',
    'Tier 1 Plus',
    'Tier 1',
    'Tier 2',
    'Tier 3',
    'Primes',
    'Subprimes',
    'VRR',
    'O2 Vape',
    '1g O2 Vapes',
    'LIQUID LIVE RESIN',
    'Full Spec',
    'Food Grade',
    'Gummies',
    'Farm Supplies',
    'Drawings'
];

const DEFAULT_WAREHOUSE = "Main Storage - MTM";
const GROUP_DEFAULT_WAREHOUSE = {
    'Fresh Frozen':  'Hemet TSBC - TSBC',
    'Tier 1 Plus':        'Main Storage - MTM',
    'Tier 1':        'Main Storage - MTM',
    'Tier 2':        'Main Storage - MTM',
    'Tier 3':        'Main Storage - MTM',
    'Primes':        'Main Storage - MTM',
    '0.5g O2 Vape':  'Conversion - MTM',
};

const LOW_STOCK_THRESHOLD = 5;

const FRESH_FROZEN_MAIN_GROUP = 'Fresh Frozen';
const FRESH_FROZEN_SUBGROUPS = [
    'Fresh Frozen',
    'Fresh Frozen - BHO',
    'Fresh Frozen - SHO', 'Fresh Frozen Untested', 'Fresh Frozen - To Be Determined'
];

// ---------------------------------------------------
// STATE
// ---------------------------------------------------

let CURRENT_GROUP = null;
let CURRENT_ITEMS = [];
let CURRENT_FILTERED_ITEMS = [];
let CURRENT_HAS_WAREHOUSE = false;

let GROUP_PROJECTS = []; // the group's projects with stock showing, each with its warehouses
let PROJECT_LABELS = {}; // project name -> project_name, as last listed

// Column the table is sorted by (a SORT_COLUMNS key) and direction; null = server order.
let SORT = { key: null, dir: 'desc' };

let FILTERS = {
    project: '__ALL__',
    warehouses: [], // picked warehouses; empty = All Warehouses
    search: '',
    onlyAvailable: false,
    lowStockOnly: false,
    highStockOnly: false, // Fresh Frozen: 100 lbs or more on hand
    ffType: 'all' // Fresh Frozen type button: all / SHO / BHO / TBD / Untested
};

// ---------------------------------------------------
// HELPERS
// ---------------------------------------------------

function getDefaultWarehouse(group) {
    return GROUP_DEFAULT_WAREHOUSE[group] || DEFAULT_WAREHOUSE;
}

function isFreshFrozenCombinedView(group) {
    return group === FRESH_FROZEN_MAIN_GROUP;
}

function getLoadGroups(group) {
    if (isFreshFrozenCombinedView(group)) {
        return FRESH_FROZEN_SUBGROUPS.slice();
    }
    return [group];
}

function getTypeLabel(item) {
    const itemGroup = String(item.item_group || '').trim();

    if (itemGroup === 'Fresh Frozen - BHO') return 'BHO';
    if (itemGroup === 'Fresh Frozen - SHO') return 'SHO';
    if (itemGroup === 'Fresh Frozen Untested') return 'Untested';
    if (itemGroup === 'Fresh Frozen - To Be Determined') return 'TBD';
    return '';
}

function getTypeClass(typeLabel) {
    if (typeLabel === 'BHO') return 'type-badge type-bho';
    if (typeLabel === 'SHO') return 'type-badge type-sho';
    if (typeLabel === 'TBD') return 'type-badge type-tbd';
    if (typeLabel === 'Untested') return 'type-badge type-untested';
    return '';
}

function escapeRegex(string) {
    return String(string).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Yields: ours (Lab Tolling, manufacturing runs) are purple; each customer's
// reported yields come with a named colour from the server, the same every time.
function customerBadgeStyle(p) {
    return `background:${p.bg};color:${p.fg};border-color:${p.swatch || p.fg}`;
}

function legendItem(swatch, colourName, label) {
    return `<span class="yield-legend-item"><span class="yield-legend-swatch" style="background:${swatch}"></span><b>${escapeHtml(colourName)}</b> = ${escapeHtml(label)}</span>`;
}

// Key above the summary cards, by colour name: Purple = ours, then every
// customer whose yields are in the table. Fresh Frozen views only.
function renderYieldLegend(items) {
    const el = document.getElementById('yield-legend');
    if (!el) return;
    if (!isFreshFrozenCombinedView(CURRENT_GROUP)) {
        el.hidden = true;
        return;
    }

    const customers = {};
    (items || []).forEach(function (item) {
        (item.yield_to_hash_parts || []).concat(item.hash_to_rosin_parts || [], item.bho_yield_parts || []).forEach(function (p) {
            if (p.source === 'customer') customers[p.customer] = p;
        });
    });

    const entries = Object.values(customers)
        .sort(function (a, b) { return String(a.customer_name).localeCompare(String(b.customer_name)); })
        .map(function (p) { return legendItem(p.swatch || p.fg, p.color, p.customer_name || p.customer); })
        .join('');

    el.innerHTML = `
        <span class="yield-legend-title">Yield colours</span>
        ${legendItem('var(--mt-purple)', 'Purple', 'Our yields')}
        ${entries || '<span class="yield-legend-none">Customer yields get their own colour per customer; none in this view yet</span>'}`;
    el.hidden = false;
}

function renderYieldBadges(parts, fallback) {
    if (!parts || !parts.length) {
        return fallback ? `<span class="yield-badge">${escapeHtml(fallback)}</span>` : '';
    }
    return parts.map((p) => {
        if (p.source !== 'customer') {
            return `<span class="yield-badge" title="Purple = Our yields">${escapeHtml(p.value)}</span>`;
        }
        return `<span class="yield-badge yield-badge-customer" style="${customerBadgeStyle(p)}" title="${escapeHtml(p.color)} = ${escapeHtml(p.customer_name || p.customer)}">${escapeHtml(p.value)}</span>`;
    }).join('');
}

function escapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function cleanItemName(itemName, itemGroup) {
    if (!itemName) return '-';

    let name = String(itemName);

    if (itemGroup) {
        let groupSuffix = new RegExp('\\s*[-]\\s*' + escapeRegex(itemGroup) + '$', 'i');
        name = name.replace(groupSuffix, '');
    }

    if (itemGroup) {
        let underscoreGroupPattern = new RegExp('[_][A-Za-z0-9][-]' + escapeRegex(itemGroup) + '$', 'i');
        name = name.replace(underscoreGroupPattern, '');
    }

    name = name.replace(/_CDC$/i, '');
    name = name.replace(/_[A-Za-z0-9]$/i, '');
    name = name.replace(/_/g, ' ');
    name = name.trim();

    return name || String(itemName);
}

// 55854.49 -> "55,854.49" for display; CSV export keeps plain numbers.
function fmtQty(val) {
    return parseNum(val).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function parseNum(val) {
    let n = parseFloat(val || 0);
    return isNaN(n) ? 0 : n;
}

function getAvailable(item) {
    return parseNum(item.actual_qty) - parseNum(item.reserved_qty);
}

function getStatusClass(available) {
    if (available <= 0) return 'status-out';
    if (available <= LOW_STOCK_THRESHOLD) return 'status-low';
    return 'status-good';
}

function getStatusLabel(available) {
    if (available <= 0) return 'Out of Stock';
    if (available <= LOW_STOCK_THRESHOLD) return 'Low Stock';
    return 'Available';
}

function debounce(fn, delay) {
    let timer = null;
    return function () {
        const context = this;
        const args = arguments;
        clearTimeout(timer);
        timer = setTimeout(function () {
            fn.apply(context, args);
        }, delay);
    };
}

function decodeHtmlEntities(str) {
    const txt = document.createElement('textarea');
    txt.innerHTML = str;
    return txt.value;
}

function deduplicateItems(items) {
    const seen = {};
    const output = [];

    items.forEach(function (item) {
        const key = [
            String(item.item_code || '').trim(),
            String(item.warehouse || '').trim(),
            String(item.item_group || '').trim()
        ].join('||');

        if (!seen[key]) {
            seen[key] = true;
            output.push(item);
        }
    });

    return output;
}

function csvEscape(value) {
    if (value === null || value === undefined) return '';
    const str = String(value);
    return '"' + str.replace(/"/g, '""') + '"';
}

// ---------------------------------------------------
// BINDINGS
// ---------------------------------------------------

function bindGlobalFilters() {
    const searchEl = document.getElementById('search-box');
    const warehouseEl = document.getElementById('warehouse-filter');
    const projectEl = document.getElementById('project-filter');
    const onlyAvailableEl = document.getElementById('only-available');
    const lowStockOnlyEl = document.getElementById('low-stock-only');
    const resetBtn = document.getElementById('reset-filters-btn');

    // A project's stock comes from the ledger, not Bin, so picking one
    // reloads the group (keeping the other filters as they are).
    if (projectEl) {
        projectEl.addEventListener('change', function () {
            FILTERS.project = this.value;
            if (CURRENT_GROUP) loadStock(CURRENT_GROUP, true);
        });
    }

    if (searchEl) {
        searchEl.addEventListener('input', debounce(function () {
            FILTERS.search = this.value.trim().toLowerCase();
            renderWithFilters();
        }, 200));
    }

    if (warehouseEl) bindWarehouseMulti(warehouseEl);

    if (onlyAvailableEl) {
        onlyAvailableEl.addEventListener('change', function () {
            FILTERS.onlyAvailable = this.checked;
            renderWithFilters();
        });
    }

    if (lowStockOnlyEl) {
        lowStockOnlyEl.addEventListener('change', function () {
            FILTERS.lowStockOnly = this.checked;
            renderWithFilters();
        });
    }

    const highStockOnlyEl = document.getElementById('high-stock-only');
    if (highStockOnlyEl) {
        highStockOnlyEl.addEventListener('change', function () {
            FILTERS.highStockOnly = this.checked;
            renderWithFilters();
        });
    }

    if (resetBtn) {
        resetBtn.addEventListener('click', function () {
            const hadProject = FILTERS.project !== '__ALL__';
            resetFiltersToDefault();
            if (hadProject && CURRENT_GROUP) loadStock(CURRENT_GROUP, true);
            else renderWithFilters();
        });
    }
}

function bindGroupSearch() {
    const input = document.getElementById('group-search');
    if (input) input.addEventListener('input', filterGroupList);
}

function filterGroupList() {
    const input = document.getElementById('group-search');
    const term = input ? input.value.trim().toLowerCase() : '';
    let shown = 0;
    document.querySelectorAll('#group-list .item-group-btn').forEach(function (btn) {
        const match = !term || btn.textContent.toLowerCase().includes(term);
        btn.hidden = !match;
        if (match) shown++;
    });
    const empty = document.querySelector('#group-list .group-empty');
    if (empty) empty.hidden = shown > 0;
}

const GROUPS_COLLAPSED_KEY = 'mtm_inventory_dashboard_groups_collapsed';

// Wide screens: the « button folds the groups sidebar into a slim rail so the
// table gets the room. Remembered per browser.
function setGroupsCollapsed(collapsed) {
    const layout = document.getElementById('mt-layout');
    const btn = document.getElementById('sidebar-collapse');
    if (!layout || !btn) return;
    layout.classList.toggle('groups-collapsed', collapsed);
    const label = collapsed ? 'Show item groups' : 'Hide item groups';
    btn.title = label;
    btn.setAttribute('aria-label', label);
    btn.setAttribute('aria-expanded', String(!collapsed));
    storageSet(GROUPS_COLLAPSED_KEY, collapsed ? '1' : '');
}

function bindSidebarToggle() {
    const collapseBtn = document.getElementById('sidebar-collapse');
    if (collapseBtn) {
        setGroupsCollapsed(storageGet(GROUPS_COLLAPSED_KEY) === '1');
        collapseBtn.addEventListener('click', function (e) {
            e.stopPropagation();
            const layout = document.getElementById('mt-layout');
            setGroupsCollapsed(!layout.classList.contains('groups-collapsed'));
        });
    }

