const FF_TYPE_BUTTONS = [
    { key: 'all', label: 'All' },
    { key: 'SHO', label: 'SHO' },
    { key: 'BHO', label: 'BHO' },
    { key: 'TBD', label: 'TBD' },
    { key: 'Untested', label: 'Untested' }
];

function renderFfTypeButtons(counts) {
    const el = document.getElementById('ff-type-filter');
    if (!el) return;
    if (!isFreshFrozenCombinedView(CURRENT_GROUP)) {
        el.hidden = true;
        el.innerHTML = '';
        return;
    }
    el.hidden = false;
    el.innerHTML = '<span class="ff-type-label">Type</span>' + FF_TYPE_BUTTONS.map(function (b) {
        const active = FILTERS.ffType === b.key ? ' active' : '';
        const n = counts && counts[b.key] !== undefined ? counts[b.key] : 0;
        return '<button type="button" class="ff-type-btn' + active + '" data-ff-type="' + b.key + '" aria-pressed="' +
            (active ? 'true' : 'false') + '">' + b.label + ' <span class="ff-type-count">' + n + '</span></button>';
    }).join('');
}

document.addEventListener('click', function (e) {
    const btn = e.target.closest ? e.target.closest('.ff-type-btn') : null;
    if (!btn) return;
    FILTERS.ffType = btn.getAttribute('data-ff-type') || 'all';
    renderWithFilters();
});

function renderWithFilters() {
    if (!CURRENT_ITEMS || !CURRENT_ITEMS.length) {
        CURRENT_FILTERED_ITEMS = [];
        renderSummary([]);
        populateWarehouseDropdown([]);
        renderProjectOptions();
        document.getElementById('stock-table').innerHTML =
            '<div class="empty-state">No items found for this group</div>';
        return;
    }

    if (!CURRENT_HAS_WAREHOUSE) {
        CURRENT_FILTERED_ITEMS = [];
        renderSummary([]);
        populateWarehouseDropdown([]);
        document.getElementById('stock-table').innerHTML = `
            <div class="alert alert-danger mb-0">
                Warehouse field is missing from the API response. Front end warehouse filtering cannot work until warehouse is included in the backend response.
            </div>
        `;
        return;
    }

    const warehouses = Array.from(
        new Set(
            CURRENT_ITEMS
                .map(function (i) { return i.warehouse; })
                .filter(Boolean)
        )
    ).sort();

    // Drop picked warehouses this group has nothing in; none left = All Warehouses.
    FILTERS.warehouses = FILTERS.warehouses.filter(function (w) { return warehouses.includes(w); });
    populateWarehouseDropdown(warehouses);

    renderProjectOptions();

    const ffView = isFreshFrozenCombinedView(CURRENT_GROUP);
    setStockToggles(ffView);
    const typeCounts = { all: 0, SHO: 0, BHO: 0, TBD: 0, Untested: 0 };

    const filtered = CURRENT_ITEMS.filter(function (item) {
        const available = getAvailable(item);
        const cleanedName = cleanItemName(item.item_name, item.item_group || CURRENT_GROUP);
        const typeLabel = getTypeLabel(item);

        const searchText = (
            String(item.item_code || '') + ' ' +
            String(cleanedName || '') + ' ' +
            String(typeLabel || '') + ' ' +
            String(item.propagation || '') + ' ' +
            String(item.breeder || '') + ' ' +
            String(item.yield_to_hash || '') + ' ' +
            String(item.hash_to_rosin || '') + ' ' +
            String(item.bho_yield || '')
        ).toLowerCase();

        if (FILTERS.warehouses.length && !FILTERS.warehouses.includes(String(item.warehouse || '').trim())) {
            return false;
        }

        if (FILTERS.search && !searchText.includes(FILTERS.search)) {
            return false;
        }

        if (FILTERS.onlyAvailable && available <= 0) {
            return false;
        }

        if (!ffView && FILTERS.lowStockOnly && !(available > 0 && available <= LOW_STOCK_THRESHOLD)) {
            return false;
        }

        if (ffView && FILTERS.highStockOnly && !(Number(item.actual_qty) >= HIGH_STOCK_LBS)) {
            return false;
        }

        if (ffView) {
            typeCounts.all += 1;
            if (typeCounts[typeLabel] !== undefined) typeCounts[typeLabel] += 1;
            if (FILTERS.ffType !== 'all' && typeLabel !== FILTERS.ffType) return false;
        }

        return true;
    });

    renderFfTypeButtons(typeCounts);
    CURRENT_FILTERED_ITEMS = sortItems(filtered);
    renderSummary(filtered);
    renderStockTable(CURRENT_FILTERED_ITEMS);
}

// The group's projects with stock showing on the dashboard, from the server.
function setGroupProjects(projects) {
    const seen = {};
    GROUP_PROJECTS = [];
    // Fresh Frozen loads three groups; one project can be in several.
    projects.forEach(function (p) {
        if (!p || !p.name) return;
        if (!seen[p.name]) {
            seen[p.name] = { name: p.name, project_name: p.project_name || p.name, warehouses: [] };
            PROJECT_LABELS[p.name] = seen[p.name].project_name;
            GROUP_PROJECTS.push(seen[p.name]);
        }
        (p.warehouses || []).forEach(function (w) {
            if (!seen[p.name].warehouses.includes(w)) seen[p.name].warehouses.push(w);
        });
    });
}

// Only the projects with stock in the chosen warehouses (all of the group's
// with All Warehouses). A project already picked stays listed and selected,
// even where it holds nothing, so the choice is never silently dropped.
function renderProjectOptions() {
    const options = GROUP_PROJECTS.filter(function (p) {
        return !FILTERS.warehouses.length || (p.warehouses || []).some(function (w) {
            return FILTERS.warehouses.includes(w);
        });
    });
    if (FILTERS.project !== '__ALL__' && !options.some(function (p) { return p.name === FILTERS.project; })) {
        options.push({ name: FILTERS.project, project_name: getProjectLabel(FILTERS.project) });
    }
    options.sort(function (a, b) {
        return String(a.project_name).localeCompare(String(b.project_name), undefined, { numeric: true });
    });

    let html = '<option value="__ALL__">All Projects</option>';
    options.forEach(function (p) {
        html += `<option value="${escapeHtml(p.name)}">${escapeHtml(p.project_name || p.name)}</option>`;
    });

    const projectEl = document.getElementById('project-filter');
    if (projectEl) {
        projectEl.innerHTML = html;
        projectEl.value = FILTERS.project;
    }
}

function getProjectLabel(project) {
    return PROJECT_LABELS[project] || project;
}

function projectHeadingSuffix() {
    return FILTERS.project !== '__ALL__' ? ' · ' + getProjectLabel(FILTERS.project) : '';
}

// Warehouse filter: a dropdown of checkboxes, so several warehouses can be
// picked at once. "All Warehouses" clears the picks; unticking the last one
// goes back to All.
function populateWarehouseDropdown(warehouses) {
    const all = !FILTERS.warehouses.length;
    let html = `<label class="wh-multi-option wh-multi-all"><input type="checkbox" value="__ALL__"${all ? ' checked' : ''}> All Warehouses</label>`;

    warehouses.forEach(function (w) {
        const checked = FILTERS.warehouses.includes(w) ? ' checked' : '';
        html += `<label class="wh-multi-option"><input type="checkbox" value="${escapeHtml(w)}"${checked}> ${escapeHtml(w)}</label>`;
    });

    const menuEl = document.getElementById('warehouse-filter-menu');
    if (menuEl) menuEl.innerHTML = html;

    const labelEl = document.getElementById('warehouse-filter-label');
    if (labelEl) {
        labelEl.textContent = all ? 'All Warehouses'
            : FILTERS.warehouses.length === 1 ? FILTERS.warehouses[0]
            : FILTERS.warehouses.length + ' warehouses';
        labelEl.parentElement.title = all ? '' : FILTERS.warehouses.join(', ');
    }
}

function bindWarehouseMulti(wrapEl) {
    const btn = document.getElementById('warehouse-filter-btn');
    const menu = document.getElementById('warehouse-filter-menu');
    if (!btn || !menu) return;

    function setOpen(open) {
        menu.hidden = !open;
        btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    }

    btn.addEventListener('click', function () { setOpen(menu.hidden); });

    document.addEventListener('click', function (e) {
        if (!menu.hidden && !wrapEl.contains(e.target)) setOpen(false);
    });
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && !menu.hidden) { setOpen(false); btn.focus(); }
    });

    menu.addEventListener('change', function (e) {
        const box = e.target;
        if (!box || box.type !== 'checkbox') return;
        if (box.value === '__ALL__') {
            FILTERS.warehouses = [];
        } else if (box.checked) {
            if (!FILTERS.warehouses.includes(box.value)) FILTERS.warehouses.push(box.value);
        } else {
            FILTERS.warehouses = FILTERS.warehouses.filter(function (w) { return w !== box.value; });
        }
        renderWithFilters();
    });
}

