// T1/T2/T3 share of the rosin traced back to this item through its Stock Entries.
const QUALITY_TIERS = [['t1', 'T1'], ['t2', 'T2'], ['t3', 'T3']];
const BLANK_CELL = '<span class="cell-blank">—</span>';

function renderQualityGrade(grade) {
    if (!grade) return BLANK_CELL;
    return '<span class="yield-badges">' + QUALITY_TIERS.map(function (t) {
        const pct = parseNum(grade[t[0] + '_pct']);
        return `<span class="grade-badge grade-${t[0]}${pct ? '' : ' grade-zero'}">${t[1]} ${pct.toFixed(1)}%</span>`;
    }).join('') + '</span>';
}

// Pictures of the tier products this item was tiered into (Manufacturing Process -> Tiering Product).
// Thumbnails, tier label on each; click opens the picture.
const TIER_PIC_MAX = 6;
const TIER_PICS = {};

function absoluteUrl(url) {
    try { return new URL(url, window.location.origin).href; } catch (e) { return url || ''; }
}

function renderTierPictures(item) {
    const pics = item.tier_pictures || [];
    if (!pics.length) return BLANK_CELL;
    TIER_PICS[item.item_code] = pics;
    const code = JSON.stringify(String(item.item_code || ''));
    const thumbs = pics.slice(0, TIER_PIC_MAX).map(function (p, i) {
        const title = [p.tier, p.item_name, p.date].filter(Boolean).join(' · ');
        return `<button type="button" class="tier-pic-btn" title="${escapeHtml(title)}" onclick='openTierPicture(${code}, ${i})'>` +
            `<img src="${escapeHtml(p.url)}" alt="${escapeHtml(title)}" loading="lazy">` +
            (p.tier ? `<span class="tier-pic-label">${escapeHtml(p.tier)}</span>` : '') + '</button>';
    }).join('');
    const more = pics.length > TIER_PIC_MAX
        ? `<button type="button" class="tier-pic-more" title="See all ${pics.length} pictures" onclick='openTierPicture(${code}, ${TIER_PIC_MAX})'>+${pics.length - TIER_PIC_MAX}</button>`
        : '';
    return `<span class="tier-pics">${thumbs}${more}</span>`;
}

let TIER_PIC_VIEW = null;

function openTierPicture(itemCode, index) {
    const pics = TIER_PICS[itemCode] || [];
    if (!pics.length) return;
    let box = document.getElementById('tier-pic-lightbox');
    if (!box) {
        box = document.createElement('div');
        box.id = 'tier-pic-lightbox';
        box.className = 'tier-pic-lightbox';
        box.innerHTML = `
            <div class="tier-pic-stage" role="dialog" aria-modal="true" aria-label="Tier product picture">
                <button type="button" class="tier-pic-close" aria-label="Close">×</button>
                <button type="button" class="tier-pic-nav tier-pic-prev" aria-label="Previous picture">‹</button>
                <a class="tier-pic-full-link" target="_blank" rel="noopener"><img class="tier-pic-full" alt=""></a>
                <button type="button" class="tier-pic-nav tier-pic-next" aria-label="Next picture">›</button>
                <div class="tier-pic-caption"></div>
            </div>`;
        document.body.appendChild(box);
        box.addEventListener('click', function (e) {
            if (e.target === box || e.target.classList.contains('tier-pic-close')) closeTierPicture();
            else if (e.target.classList.contains('tier-pic-prev')) stepTierPicture(-1);
            else if (e.target.classList.contains('tier-pic-next')) stepTierPicture(1);
        });
        document.addEventListener('keydown', function (e) {
            if (!TIER_PIC_VIEW) return;
            if (e.key === 'Escape') closeTierPicture();
            else if (e.key === 'ArrowLeft') stepTierPicture(-1);
            else if (e.key === 'ArrowRight') stepTierPicture(1);
        });
    }
    TIER_PIC_VIEW = { pics: pics, index: Math.min(index, pics.length - 1) };
    showTierPicture();
    box.classList.add('open');
}

function stepTierPicture(delta) {
    if (!TIER_PIC_VIEW) return;
    const n = TIER_PIC_VIEW.pics.length;
    TIER_PIC_VIEW.index = (TIER_PIC_VIEW.index + delta + n) % n;
    showTierPicture();
}

function showTierPicture() {
    const box = document.getElementById('tier-pic-lightbox');
    const p = TIER_PIC_VIEW.pics[TIER_PIC_VIEW.index];
    const n = TIER_PIC_VIEW.pics.length;
    box.querySelector('.tier-pic-full').src = p.url;
    box.querySelector('.tier-pic-full-link').href = p.url;
    box.querySelector('.tier-pic-caption').innerHTML =
        (p.tier ? `<span class="tier-pic-label">${escapeHtml(p.tier)}</span> ` : '') +
        `<b>${escapeHtml(p.item_name || '')}</b>` +
        (p.qty ? ` · ${escapeHtml(String(p.qty))} ${escapeHtml(p.uom || '')}` : '') +
        (p.date ? ` · ${escapeHtml(p.date)}` : '') +
        (n > 1 ? ` <span class="tier-pic-count">${TIER_PIC_VIEW.index + 1} / ${n}</span>` : '');
    box.querySelectorAll('.tier-pic-nav').forEach(function (b) { b.hidden = n < 2; });
}

function closeTierPicture() {
    const box = document.getElementById('tier-pic-lightbox');
    if (box) box.classList.remove('open');
    TIER_PIC_VIEW = null;
}

function qualityGradeText(grade) {
    if (!grade) return '';
    return QUALITY_TIERS.map(function (t) {
        return t[1] + ' ' + parseNum(grade[t[0] + '_pct']).toFixed(1) + '%';
    }).join(', ');
}

// Clone / Seed and Breeder / Source: always in the Fresh Frozen view, and in
// any other group once one of its items has either filled in.
function showGeneticsColumns() {
    return isFreshFrozenCombinedView(CURRENT_GROUP) || CURRENT_ITEMS.some(function (i) {
        return i.propagation || i.breeder;
    });
}

