// SORTING
// ---------------------------------------------------

// Click a column header to sort; click again to flip. Numbers start highest
// first, text A-Z. Blank values always go last. Remembered per browser.
const SORT_STORAGE_KEY = 'mtm_inventory_dashboard_sort';

// Yield cells can hold several % values (lab, runs, customers): sort by their average.
// Average of every Yield To Hash value (server: inventory_dashboard.yield_to_hash_values);
// the same number decides SHO / BHO / TBD / Untested.
function renderAvgYield(v, kind) {
    if (v === null || v === undefined || v === '' || isNaN(parseFloat(v))) return BLANK_CELL;
    const n = parseFloat(v);
    if (kind === 'bho') {
        return `<span class="avg-yth avg-bho" title="Average of all BHO Yield values">${n.toFixed(2)}%</span>`;
    }
    return `<span class="avg-yth ${n >= 2.5 ? 'avg-yth-high' : 'avg-yth-low'}" title="Average of all Yield to Hash values">${n.toFixed(2)}%</span>`;
}

// Fresh Frozen view: header cells outside Run to SHO / Run to BHO span both header rows.
function thSpan2(html) {
    return html.replace('<th ', '<th rowspan="2" ');
}



function avgYield(parts, fallback) {
    let values = (parts || []).map(function (p) { return parseFloat(p.value); });
    if (!values.length && fallback) {
        values = String(fallback).split(',').map(function (v) { return parseFloat(v); });
    }
    values = values.filter(function (v) { return !isNaN(v); });
    if (!values.length) return null;
    return values.reduce(function (a, b) { return a + b; }, 0) / values.length;
}

const SORT_COLUMNS = {
    item_code:     { type: 'text', get: function (i) { return i.item_code; } },
    item_name:     { type: 'text', get: function (i) { return cleanItemName(i.item_name, i.item_group || CURRENT_GROUP); } },
    type:          { type: 'text', get: function (i) { const t = getTypeLabel(i); return t ? (FF_TYPE_ORDER[t] || 5) + ' ' + t + ' ' + cleanItemName(i.item_name, i.item_group || CURRENT_GROUP) : ''; } },
    yield_to_hash_avg: { type: 'num', get: function (i) { return i.yield_to_hash_avg; } },
    propagation:   { type: 'text', get: function (i) { return i.propagation; } },
    breeder:       { type: 'text', get: function (i) { return i.breeder; } },
    actual_qty:    { type: 'num',  get: function (i) { return parseNum(i.actual_qty); } },
    reserved_qty:  { type: 'num',  get: function (i) { return parseNum(i.reserved_qty); } },
    available:     { type: 'num',  get: function (i) { return getAvailable(i); } },
    yield_to_hash: { type: 'num',  get: function (i) { return avgYield(i.yield_to_hash_parts, i.yield_to_hash); } },
    hash_to_rosin: { type: 'num',  get: function (i) { return avgYield(i.hash_to_rosin_parts, i.hash_to_rosin); } },
    bho_yield_avg: { type: 'num', get: function (i) { return i.bho_yield_avg; } },
    bho_yield:     { type: 'num',  get: function (i) { return avgYield(i.bho_yield_parts, i.bho_yield); } },
    quality_grade: { type: 'num',  get: function (i) { return i.quality_grade ? parseNum(i.quality_grade.t1_pct) : null; } },
    tier_pictures: { type: 'num',  get: function (i) { return (i.tier_pictures || []).length || null; } },
    warehouse:     { type: 'text', get: function (i) { return i.warehouse; } },
    note:          { type: 'text', get: function (i) { return itemNote(i.item_code, i.note); } }
};

// Fresh Frozen default order, same as /fresh-frozen-live: SHO, BHO, TBD, Untested, then by name.
const FF_TYPE_ORDER = { SHO: 1, BHO: 2, TBD: 3, Untested: 4 };

function ffTypeRank(item) {
    return FF_TYPE_ORDER[getTypeLabel(item)] || 5;
}

function sortByFfType(items) {
    return items
        .map(function (item, idx) { return { item: item, idx: idx }; })
        .sort(function (a, b) {
            const r = ffTypeRank(a.item) - ffTypeRank(b.item);
            if (r) return r;
            const an = cleanItemName(a.item.item_name, a.item.item_group || CURRENT_GROUP);
            const bn = cleanItemName(b.item.item_name, b.item.item_group || CURRENT_GROUP);
            return String(an).localeCompare(String(bn), undefined, { numeric: true, sensitivity: 'base' }) || (a.idx - b.idx);
        })
        .map(function (x) { return x.item; });
}

function sortItems(items) {
    const col = SORT.key && SORT_COLUMNS[SORT.key];
    if (!col) return isFreshFrozenCombinedView(CURRENT_GROUP) ? sortByFfType(items) : items;
    const sign = SORT.dir === 'asc' ? 1 : -1;
    return items
        .map(function (item, idx) { return { item: item, idx: idx, v: col.get(item) }; })
        .sort(function (a, b) {
            const blankA = a.v === null || a.v === undefined || a.v === '';
            const blankB = b.v === null || b.v === undefined || b.v === '';
            if (blankA || blankB) return (blankA - blankB) || (a.idx - b.idx);
            const cmp = col.type === 'num'
                ? a.v - b.v
                : String(a.v).localeCompare(String(b.v), undefined, { numeric: true, sensitivity: 'base' });
            return (cmp * sign) || (a.idx - b.idx);
        })
        .map(function (x) { return x.item; });
}

// Status sorts by Available, so its header shares that key but keeps its own arrow.
function sortableTh(key, label, extraClass, id) {
    const thisId = id || key;
    const active = SORT.key === key && (SORT.th || key) === thisId;
    const arrow = active ? (SORT.dir === 'asc' ? '▲' : '▼') : '↕';
    return `<th class="sortable-th${extraClass ? ' ' + extraClass : ''}${active ? ' sorted' : ''}" data-sort="${key}" data-sort-id="${thisId}" title="Sort by ${escapeHtml(label)}">${escapeHtml(label)}<span class="sort-arrow">${arrow}</span></th>`;
}

function bindTableSort() {
    try {
        const saved = JSON.parse(storageGet(SORT_STORAGE_KEY) || 'null');
        if (saved && SORT_COLUMNS[saved.key]) SORT = saved;
    } catch (e) { /* bad saved value: start unsorted */ }

    const table = document.getElementById('stock-table');
    if (!table) return;
    table.addEventListener('click', function (e) {
        const th = e.target.closest('th[data-sort]');
        if (!th) return;
        const key = th.getAttribute('data-sort');
        const id = th.getAttribute('data-sort-id');
        if (SORT.key === key && (SORT.th || key) === id) {
            SORT.dir = SORT.dir === 'asc' ? 'desc' : 'asc';
        } else {
            SORT = { key: key, th: id, dir: SORT_COLUMNS[key].type === 'num' ? 'desc' : 'asc' };
        }
        storageSet(SORT_STORAGE_KEY, JSON.stringify(SORT));
        renderWithFilters();
    });
}

