function exportCurrentViewToCSV() {
    if (!CURRENT_FILTERED_ITEMS || !CURRENT_FILTERED_ITEMS.length) {
        frappe.show_alert({
            message: 'No rows available to export',
            indicator: 'orange'
        });
        return;
    }

    const isFreshFrozen = isFreshFrozenCombinedView(CURRENT_GROUP);
    const rows = [];
    const header = [];

    header.push('Item Code');
    header.push('Item Name');

    if (isFreshFrozen) {
        header.push('Type');
        header.push('Average SHO Yield %');
        header.push('Average BHO Yield %');
        header.push('Run to SHO - Yield to Hash %');
        header.push('Run to SHO - Hash to Rosin %');
        header.push('Run to BHO - Yield %');
        header.push('Quality Grade');
        header.push('Pictures');
    }

    const showGenetics = showGeneticsColumns();
    if (showGenetics) {
        header.push('Clone / Seed');
        header.push('Breeder / Source');
    }

    const projectLabel = FILTERS.project !== '__ALL__' ? getProjectLabel(FILTERS.project) : '';

    header.push('Warehouse');
    if (projectLabel) header.push('Project');
    if (isFreshFrozen) header.push('Note');
    header.push('Qty');
    header.push('Reserved');
    header.push('Available');
    header.push('Status');

    rows.push(header);

    CURRENT_FILTERED_ITEMS.forEach(function (item) {
        const row = [];
        const available = getAvailable(item);

        row.push(item.item_code || '');
        row.push(cleanItemName(item.item_name, item.item_group || CURRENT_GROUP));

        if (isFreshFrozen) {
            row.push(getTypeLabel(item));
            row.push(item.yield_to_hash_avg === null || item.yield_to_hash_avg === undefined ? '' : Number(item.yield_to_hash_avg).toFixed(2));
            row.push(item.bho_yield_avg === null || item.bho_yield_avg === undefined ? '' : Number(item.bho_yield_avg).toFixed(2));
            row.push(item.yield_to_hash || '');
            row.push(item.hash_to_rosin || '');
            row.push(item.bho_yield || '');
            row.push(qualityGradeText(item.quality_grade));
            row.push((item.tier_pictures || []).map(function (p) { return (p.tier ? p.tier + ': ' : '') + absoluteUrl(p.url); }).join(' | '));
        }

        if (showGenetics) {
            row.push(item.propagation || '');
            row.push(item.breeder || '');
        }

        row.push(item.warehouse || '');
        if (projectLabel) row.push(projectLabel);
        if (isFreshFrozen) row.push(itemNote(item.item_code, item.note));
        row.push(parseNum(item.actual_qty).toFixed(2));
        row.push(parseNum(item.reserved_qty).toFixed(2));
        row.push(available.toFixed(2));
        row.push(getStatusLabel(available));

        rows.push(row);
    });

    const csvContent = rows
        .map(function (row) {
            return row.map(csvEscape).join(',');
        })
        .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const safeGroupName = String((CURRENT_GROUP || 'inventory') + (projectLabel ? ' ' + projectLabel : ''))
        .replace(/\s+/g, '_')
        .replace(/[^\w\-]/g, '');

    link.href = url;
    link.download = safeGroupName + '_inventory.csv';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    frappe.show_alert({
        message: 'CSV exported successfully',
        indicator: 'green'
    });
}

