// The open group is kept in the URL hash (so a refresh or a shared link
// reopens it) and in localStorage as a fallback for a bare /inventory-dashboard.
const GROUP_STORAGE_KEY = 'mtm_inventory_dashboard_group';

function storageGet(key) {
    try { return window.localStorage.getItem(key); } catch (e) { return null; }
}

function storageSet(key, value) {
    try {
        if (value === null || value === undefined) window.localStorage.removeItem(key);
        else window.localStorage.setItem(key, value);
    } catch (e) { /* private window / blocked storage: nothing to remember */ }
}

function getSavedGroup() {
    const match = /(?:^|[#&])group=([^&]*)/.exec(window.location.hash || '');
    if (match) {
        try { return decodeURIComponent(match[1]); } catch (e) { /* fall through */ }
    }
    return storageGet(GROUP_STORAGE_KEY);
}

function saveGroup(group) {
    storageSet(GROUP_STORAGE_KEY, group);
    try {
        history.replaceState(null, '', window.location.pathname + window.location.search + '#group=' + encodeURIComponent(group));
    } catch (e) { /* old browser: the localStorage copy still works */ }
}

function restoreSavedGroup(groups) {
    const saved = getSavedGroup();
    if (saved && groups.some(function (g) { return g.name === saved; })) {
        loadStock(saved);
    }
}

