// ---------------------------------------------------

// Items picked from any group, kept in localStorage until saved as a draft
// Sales Order. Each line is one item in one warehouse.
const CART_STORAGE_KEY = 'mtm_inventory_dashboard_order';
const ORDER_API = 'cannabis_management.api.inventory_order.';

let ORDER_ENABLED = false;
let ORDER_CART = [];
let ORDER_FORM_OPTIONS = null;
let ORDER_ROW_LOOKUP = {};
// The access code, once the server accepts it. Memory only: a reload asks again.
let ORDER_CODE = null;

function cartKey(item) {
    return String(item.item_code || '') + '||' + String(item.warehouse || '');
}

function isInCart(key) {
    return ORDER_CART.some(function (line) { return line.key === key; });
}

function loadCart() {
    try {
        const lines = JSON.parse(storageGet(CART_STORAGE_KEY) || '[]');
        return Array.isArray(lines) ? lines.filter(function (l) { return l && l.item_code && l.warehouse; }) : [];
    } catch (e) {
        return [];
    }
}

function saveCart() {
    storageSet(CART_STORAGE_KEY, ORDER_CART.length ? JSON.stringify(ORDER_CART) : null);
    updateOrderButton();
}

function initOrderCart() {
    ORDER_CART = loadCart();

    // Guests can browse stock, but only a user who may create a Sales Order
    // gets the Add buttons and the order popup.
    if (!frappe.is_user_logged_in || !frappe.is_user_logged_in()) return;

    frappe.call({
        method: ORDER_API + 'get_order_form_options',
        callback: function (r) {
            const data = r && r.message;
            if (!data || !data.can_create) return;

            ORDER_FORM_OPTIONS = data;
            ORDER_ENABLED = true;
            ensureFloatingBar();

            const btn = document.getElementById('view-order-btn');
            if (btn) {
                btn.hidden = false;
                btn.addEventListener('click', openOrderModal);
            }
            updateOrderButton();
            bindOrderTableClicks();

            if (CURRENT_ITEMS && CURRENT_ITEMS.length) renderWithFilters();
        }
    });
}

function bindOrderTableClicks() {
    const table = document.getElementById('stock-table');
    if (!table) return;

    table.addEventListener('change', function (e) {
        const box = e.target.closest('.order-check');
        if (!box) return;

        const key = box.getAttribute('data-key');
        if (!box.checked) {
            removeFromCart(key);
            return;
        }
        if (isInCart(key)) return;

        const item = ORDER_ROW_LOOKUP[key];
        if (!item) return;

        ORDER_CART.push({
            key: key,
            item_code: item.item_code,
            item_name: cleanItemName(item.item_name, item.item_group || CURRENT_GROUP),
            item_group: item.item_group || CURRENT_GROUP,
            warehouse: item.warehouse,
            available: getAvailable(item),
            qty: ''
        });
        saveCart();
        setRowSelected(key, true);
    });
}

function removeFromCart(key) {
    ORDER_CART = ORDER_CART.filter(function (line) { return line.key !== key; });
    saveCart();
    setRowSelected(key, false);
    renderOrderLines();
}

function setRowSelected(key, inCart) {
    document.querySelectorAll('.order-check').forEach(function (box) {
        if (box.getAttribute('data-key') !== key) return;
        box.checked = inCart;
        const row = box.closest('tr');
        if (row) row.classList.toggle('row-selected', inCart);
    });
}

function renderOrderCell(item) {
    const key = cartKey(item);
    ORDER_ROW_LOOKUP[key] = item;

    return `
        <td class="order-check-col">
            <input type="checkbox" class="order-check" data-key="${escapeHtml(key)}"
                ${isInCart(key) ? 'checked' : ''}
                aria-label="Select ${escapeHtml(item.item_code || '')} for order">
        </td>
    `;
}

