    box: '<svg viewBox="0 0 24 24" width="34" height="34" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 8 12 3 3 8v8l9 5 9-5V8z"/><path d="m3 8 9 5 9-5M12 13v8"/></svg>'
};

function pluralize(n, word) {
    return n + ' ' + word + (n === 1 ? '' : 's');
}

function cartCompanies() {
    // Warehouse names end in the company abbreviation (" - MTM", " - TSBC").
    return Array.from(new Set(ORDER_CART.map(function (l) {
        return String(l.warehouse).split(' - ').pop();
    })));
}

function lineCurrencyInfo(line) {
    const abbr = String(line.warehouse || '').split(' - ').pop();
    const info = (ORDER_FORM_OPTIONS.currencies || {})[abbr];
    const currency = (info && info.currency) || ORDER_FORM_OPTIONS.default_currency || 'USD';
    return { abbr: abbr, currency: currency, symbol: (info && info.symbol) || currency };
}

function fmtMoney(amount, currency) {
    try {
        return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency }).format(parseNum(amount));
    } catch (e) {
        return currency + ' ' + fmtQty(amount);
    }
}

function lineAmount(line) {
    return parseNum(line.qty) * parseNum(line.rate);
}

function selectHtml(id, fieldname) {
    const field = (ORDER_FORM_OPTIONS.options || {})[fieldname] || { options: [], default: '' };
    let html = `<select id="${id}" class="form-control of-control">`;
    if (!field.reqd) html += '<option value="">Select…</option>';
    field.options.forEach(function (opt) {
        html += `<option value="${escapeHtml(opt)}" ${opt === field.default ? 'selected' : ''}>${escapeHtml(opt)}</option>`;
    });
    return html + '</select>';
}

function fieldLabel(fieldname, fallback) {
    const field = (ORDER_FORM_OPTIONS.options || {})[fieldname];
    return escapeHtml((field && field.label) || fallback);
}

function ensureFloatingBar() {
    if (document.getElementById('order-float')) return;
    const bar = document.createElement('button');
    bar.type = 'button';
    bar.id = 'order-float';
    bar.className = 'mt-order-float';
    bar.hidden = true;
    bar.innerHTML = `
        <span class="mt-order-float-icon">${ORDER_ICONS.cart}</span>
        <span class="mt-order-float-text" id="order-float-text"></span>
        <span class="mt-order-float-cta">View Order ${ORDER_ICONS.arrow}</span>
    `;
    bar.addEventListener('click', openOrderModal);
    document.body.appendChild(bar);
}

function updateOrderButton() {
    const n = ORDER_CART.length;

    const countEl = document.getElementById('order-count');
    if (countEl) countEl.innerText = n;

    const btn = document.getElementById('view-order-btn');
    if (btn) btn.classList.toggle('has-items', n > 0);

    const bar = document.getElementById('order-float');
    const modal = document.getElementById('order-modal');
    if (bar) {
        bar.hidden = !ORDER_ENABLED || !n || (modal && !modal.hidden);
        const text = document.getElementById('order-float-text');
        if (text) text.innerText = pluralize(n, 'item') + ' selected';
    }

    updateOrderSubtitle();
}

function updateOrderSubtitle() {
    const sub = document.getElementById('order-modal-sub');
    if (!sub) return;
    const n = ORDER_CART.length;
    const companies = cartCompanies();
    sub.innerText = n
        ? pluralize(n, 'item') + (companies.length > 1 ? ' · ' + companies.length + ' companies' : '')
        : 'No items selected';
}

