        if (e.target === modal) return closeOrderModal();
        const actionEl = e.target.closest('[data-action]');
        if (actionEl) {
            const action = actionEl.getAttribute('data-action');
            if (action === 'close') closeOrderModal();
            else if (action === 'clear') clearOrderLines();
            else if (action === 'save') saveOrder();
            else if (action === 'new') showOrderFormView();
            return;
        }
        const removeBtn = e.target.closest('.ol-remove');
        if (removeBtn) removeFromCart(removeBtn.getAttribute('data-key'));
    });

    modal.addEventListener('input', function (e) {
        const target = e.target;
        if (target.classList.contains('of-control')) {
            target.classList.remove('is-invalid');
            showOrderError('');
