}

function saveOrder() {
    showOrderError('');

    if (!ORDER_CART.length) {
        return showOrderError('Select at least one item for the order.');
    }

    const missingQty = ORDER_CART.find(function (l) { return !(parseNum(l.qty) > 0); });
    if (missingQty) {
        const input = document.querySelector('.ol-qty[data-key="' + CSS.escape(missingQty.key) + '"]');
        return showOrderError('Enter a qty for ' + missingQty.item_name + '.', input);
    }

    const details = readOrderForm();
    if (!details.customer) return showOrderError('Select a customer.', document.getElementById('of-customer'));
    if (!details.delivery_date) return showOrderError('Set a delivery date.', document.getElementById('of-delivery-date'));
    if (!details.custom_mode_of_payment) return showOrderError('Select a mode of payment.', document.getElementById('of-mop'));

    frappe.call({
        method: ORDER_API + 'create_draft_sales_orders',
        args: {
            items: ORDER_CART.map(function (l) {
                return { item_code: l.item_code, warehouse: l.warehouse, qty: parseNum(l.qty), rate: parseNum(l.rate) };
            }),
            details: details,
            code: ORDER_CODE
        },
        btn: document.getElementById('order-save-btn'),
        freeze: true,
        callback: function (r) {
            const created = (r && r.message) || [];
            if (!created.length) return;

            const keys = ORDER_CART.map(function (l) { return l.key; });
            ORDER_CART = [];
            saveCart();
            keys.forEach(function (key) { setRowSelected(key, false); });
            resetOrderForm();
            showOrderSuccess(created);
        }
    });
}

