function openReserveModal() {
    ensureReserveModal();
    document.getElementById('reserve-modal').hidden = false;
    document.body.classList.add('mt-modal-open');
    loadReservedOrders();
}

function closeReserveModal() {
    const modal = document.getElementById('reserve-modal');
    if (modal) modal.hidden = true;
    document.body.classList.remove('mt-modal-open');
}

function loadReservedOrders() {
    const list = document.getElementById('reserve-list');
    list.innerHTML = '<div class="loading-state">Loading reserved orders...</div>';
    frappe.call({
        method: RESERVE_API,
        callback: function (r) {
            RESERVED_ORDERS = (r && r.message) || [];
            renderReservedOrders();
        },
        error: function () {
            list.innerHTML = '<div class="reserve-empty">Could not load reserved orders.</div>';
        }
    });
}

function reserveDate(value) {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(value || '');
    return m ? m[2] + '-' + m[3] + '-' + m[1] : (value || '');
}

function renderReservedOrders() {
    const list = document.getElementById('reserve-list');
    const sub = document.getElementById('reserve-modal-sub');
    const term = (document.getElementById('reserve-search').value || '').trim().toLowerCase();

    const orders = RESERVED_ORDERS.map(function (so) {
        const head = [so.name, so.customer, so.customer_name, so.company].join(' ').toLowerCase();
        if (!term || head.includes(term)) return so;
        const items = so.items.filter(function (it) {
            return [it.item_code, it.item_name, it.warehouse, it.project].join(' ').toLowerCase().includes(term);
        });
        return items.length ? Object.assign({}, so, { items: items }) : null;
    }).filter(Boolean);

    const lineCount = orders.reduce(function (n, so) { return n + so.items.length; }, 0);
    sub.innerText = pluralize(orders.length, 'order') + ' · ' + pluralize(lineCount, 'reserved line');

    if (!orders.length) {
        list.innerHTML = `<div class="reserve-empty">${term ? 'No reserved orders match your search.' : 'No sales orders have stock reserved.'}</div>`;
        return;
    }

    list.innerHTML = orders.map(function (so) {
        const rows = so.items.map(function (it) {
            return `
                <tr>
                    <td><strong>${escapeHtml(it.item_code)}</strong><div class="reserve-muted">${escapeHtml(it.item_name || '')}</div></td>
                    <td>${escapeHtml(it.warehouse)}</td>
                    <td class="num">${fmtQty(it.reserved_qty)}</td>
                    <td class="num">${fmtQty(it.delivered_qty)}</td>
                    <td class="num"><strong>${fmtQty(it.open_qty)}</strong> <span class="reserve-muted">${escapeHtml(it.stock_uom || '')}</span></td>
                    <td><span class="reserve-status">${escapeHtml(it.status)}</span></td>
                </tr>`;
        }).join('');
        return `
            <div class="reserve-card">
                <div class="reserve-card-head">
                    <div>
                        <a class="reserve-so" href="/app/sales-order/${encodeURIComponent(so.name)}" target="_blank" rel="noopener">${escapeHtml(so.name)}</a>
                        <span class="reserve-customer">${escapeHtml(so.customer_name || so.customer)}</span>
                    </div>
                    <div class="reserve-meta">
                        <span>${escapeHtml(so.company)}</span>
                        <span>Order ${escapeHtml(reserveDate(so.transaction_date))}</span>
                        <span>Delivery ${escapeHtml(reserveDate(so.delivery_date))}</span>
                        <span class="reserve-status">${escapeHtml(so.status)}</span>
                    </div>
                </div>
                <div class="reserve-table-wrap">
                    <table class="reserve-table">
                        <thead><tr>
                            <th>Item</th><th>Warehouse</th><th class="num">Reserved</th><th class="num">Delivered</th><th class="num">Open</th><th>Status</th>
                        </tr></thead>
                        <tbody>${rows}</tbody>
                    </table>
                </div>
            </div>`;
    }).join('');
}

