    if (yfNum('yf-hash') && yfNum('yf-rosin')) document.getElementById('yf-htr').value = (yfNum('yf-rosin') / yfNum('yf-hash') * 100).toFixed(2);
    if (rawG && yfNum('yf-bho-g')) document.getElementById('yf-bho').value = (yfNum('yf-bho-g') / rawG * 100).toFixed(2);
