    if (!val('yf-item').trim()) {
        msg.className = 'yf-msg yf-err'; msg.innerText = 'Pick an item.'; return;
    }
    btn.disabled = true;
    msg.className = 'yf-msg'; msg.innerText = 'Saving…';
    frappe.call({
        method: YIELD_API + 'add_yield',
        args: {
            item_code: val('yf-item').trim(), run_to: val('yf-run-to'), source: val('yf-source'), customer: val('yf-customer').trim() || null,
            date: val('yf-date') || null, quantity: val('yf-qty') || null, hash_qty: val('yf-hash') || null,
            yield_percentage: val('yf-yth') || null, rosin_qty: val('yf-rosin') || null, hash_to_rosin: val('yf-htr') || null,
            bho_qty: val('yf-bho-g') || null, bho_yield: val('yf-bho') || null, remarks: val('yf-remarks') || null
        },
        callback: function (r) {
            const d = (r && r.message) || {};
            msg.className = 'yf-msg yf-ok';
            msg.innerText = 'Saved as ' + d.name + '. Item group: ' + (d.item_group || '') + '. Refreshing…';
            setTimeout(function () {
                closeAddYield();
                loadStock(CURRENT_GROUP, true);
                if (window.__mtYieldsReload) window.__mtYieldsReload();
            }, 1200);
        },
        error: function (r) {
            btn.disabled = false;
            let text = 'Could not save the yield.';
            try {
                const m = r && r._server_messages ? JSON.parse(JSON.parse(r._server_messages)[0]).message : null;
                if (m) text = m.replace(/<[^>]+>/g, '');
            } catch (e) { /* keep default text */ }
            msg.className = 'yf-msg yf-err'; msg.innerText = text;
        }
    });
}

