// NOTES (Fresh Frozen view, Stock and Yields)
// ---------------------------------------------------

// One note per item, saved on the server (Inventory Item Note) and kept until
// someone changes it. The cell shows the note as text; clicking it (or Enter)
// opens an editor with Save / Cancel. Both views read ITEM_NOTES, so a note
// saved in one shows in the other without a reload.
const NOTES_API = 'cannabis_management.api.inventory_dashboard.';
let CAN_EDIT_NOTES = false;
const ITEM_NOTES = {};
const ITEM_NOTE_META = {};
const NOTE_MAX = 2000;
const NOTE_PENCIL = '<svg class="note-pencil" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>';

function itemNote(itemCode, fallback) {
    const v = ITEM_NOTES[itemCode];
    return v === undefined ? (fallback || '') : v;
}

function rememberNotes(items) {
    (items || []).forEach(function (i) {
        if (!i || !i.item_code || i.note === undefined) return;
        ITEM_NOTES[i.item_code] = i.note || '';
        if (i.note_by || i.note_at) ITEM_NOTE_META[i.item_code] = { by: i.note_by || '', at: i.note_at || '' };
    });
}

// "Nov 9, 2026" from the server's "2026-11-09 05:36:42", without a time-zone shift.
function noteDate(at) {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(at || '');
    if (!m) return '';
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return months[Number(m[2]) - 1] + ' ' + Number(m[3]) + ', ' + m[1];
}

function noteMetaHtml(itemCode) {
    const meta = ITEM_NOTE_META[itemCode];
    if (!meta || !itemNote(itemCode)) return '';
    const parts = [meta.by, noteDate(meta.at)].filter(Boolean).map(escapeHtml);
    return parts.length ? `<div class="note-meta">${parts.join(' · ')}</div>` : '';
}

function noteLoginUrl() {
    return '/login?redirect-to=' + encodeURIComponent(window.location.pathname + window.location.hash);
}

function renderNoteCell(itemCode, fallback) {
    const text = itemNote(itemCode, fallback);
    const code = escapeHtml(itemCode || '');
    if (!CAN_EDIT_NOTES) {
        if (text) return `<div class="note-view note-readonly"><span class="note-text">${escapeHtml(text)}</span></div>${noteMetaHtml(itemCode)}`;
        if (!(frappe.is_user_logged_in && frappe.is_user_logged_in())) {
            return `<a class="note-login" href="${noteLoginUrl()}">Log in to add a note</a>`;
        }
        return BLANK_CELL;
    }
    return `<div class="note-view${text ? '' : ' note-empty'}" role="button" tabindex="0" data-note-item="${code}" title="${text ? 'Click to edit the note' : 'Click to add a note'}" aria-label="${text ? 'Edit' : 'Add'} note for ${code}">`
        + `<span class="note-text">${text ? escapeHtml(text) : 'Add a note'}</span>${NOTE_PENCIL}</div>${noteMetaHtml(itemCode)}`;
}

// Redraw every cell showing this item's note (the item can be on several rows, and in both views).
function refreshNoteCells(itemCode) {
    document.querySelectorAll('.note-cell').forEach(function (cell) {
        const own = cell.querySelector('[data-note-item]');
        if (own && own.getAttribute('data-note-item') === itemCode && !cell.querySelector('.note-editor')) {
            cell.innerHTML = renderNoteCell(itemCode);
        }
    });
}

function autoGrowNote(ta) {
    ta.style.height = 'auto';
    ta.style.height = Math.min(ta.scrollHeight + 2, 240) + 'px';
}

function openNoteEditor(view) {
    const cell = view.closest('.note-cell');
    const code = view.getAttribute('data-note-item');
    if (!cell || !code || !CAN_EDIT_NOTES) return;
    const text = itemNote(code);
    cell.innerHTML = `
        <div class="note-editor" data-note-item="${escapeHtml(code)}">
            <textarea class="ff-note" maxlength="${NOTE_MAX}" rows="3" placeholder="Type a note for this item" aria-label="Note for ${escapeHtml(code)}">${escapeHtml(text)}</textarea>
            <div class="note-actions">
                <button type="button" class="note-btn note-save">Save</button>
                <button type="button" class="note-btn note-cancel">Cancel</button>
                <span class="note-status">Ctrl+Enter saves, Esc cancels</span>
            </div>
        </div>`;
    const ta = cell.querySelector('textarea.ff-note');
    autoGrowNote(ta);
    ta.focus();
    ta.setSelectionRange(ta.value.length, ta.value.length);
}

function closeNoteEditor(editor) {
    const cell = editor && editor.closest('.note-cell');
    if (!cell) return;
    const code = editor.getAttribute('data-note-item');
    cell.innerHTML = renderNoteCell(code);
}

function initNotes() {
    // Open the editor: click the note, or Enter / Space on it.
    document.addEventListener('click', function (e) {
        const view = e.target.closest && e.target.closest('.note-view[data-note-item]');
        if (view) openNoteEditor(view);
        // Save / Cancel pressed from the keyboard (mouse presses are handled on mousedown below).
        const btn = e.detail === 0 && e.target.closest && e.target.closest('.note-editor .note-btn');
        if (btn) {
            const editor = btn.closest('.note-editor');
            if (btn.classList.contains('note-save')) saveItemNote(editor);
            else closeNoteEditor(editor);
        }
    });
    document.addEventListener('keydown', function (e) {
        const view = e.target.closest && e.target.closest('.note-view[data-note-item]');
        if (view && (e.key === 'Enter' || e.key === ' ')) {
            e.preventDefault();
            openNoteEditor(view);
            return;
        }
        const ta = e.target.closest && e.target.closest('.note-editor textarea.ff-note');
        if (!ta) return;
        const editor = ta.closest('.note-editor');
        if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); saveItemNote(editor); }
        if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); closeNoteEditor(editor); }
    });
    document.addEventListener('input', function (e) {
        const ta = e.target.closest && e.target.closest('.note-editor textarea.ff-note');
        if (ta) autoGrowNote(ta);
    });
    // Buttons act on mousedown so the textarea keeps focus until they have run.
    document.addEventListener('mousedown', function (e) {
        const btn = e.target.closest && e.target.closest('.note-editor .note-btn');
        if (!btn) return;
        e.preventDefault();
        const editor = btn.closest('.note-editor');
        if (btn.classList.contains('note-save')) saveItemNote(editor);
        else closeNoteEditor(editor);
    });
    // Clicking away saves, so a typed note is never lost.
    document.addEventListener('focusout', function (e) {
        const ta = e.target.closest && e.target.closest('.note-editor textarea.ff-note');
        if (!ta) return;
        const editor = ta.closest('.note-editor');
        setTimeout(function () {
            if (!editor.isConnected || editor.contains(document.activeElement) || editor.classList.contains('is-saving')) return;
            if (ta.value.trim() === itemNote(editor.getAttribute('data-note-item'))) closeNoteEditor(editor);
            else saveItemNote(editor);
        }, 0);
    });
    if (!frappe.is_user_logged_in || !frappe.is_user_logged_in()) return;
    frappe.call({
        method: NOTES_API + 'can_edit_notes',
        callback: function (r) {
            CAN_EDIT_NOTES = !!(r && r.message);
            if (CAN_EDIT_NOTES && CURRENT_ITEMS && CURRENT_ITEMS.length) renderWithFilters();
            if (window.__mtYieldsRender) window.__mtYieldsRender();
        }
    });
}

function saveItemNote(editor) {
    if (!editor || editor.classList.contains('is-saving')) return;
    const code = editor.getAttribute('data-note-item');
    const ta = editor.querySelector('textarea.ff-note');
    const status = editor.querySelector('.note-status');
    const value = ta.value.trim();
    if (value === itemNote(code)) {
        closeNoteEditor(editor);
        return;
    }
    editor.classList.add('is-saving');
    editor.classList.remove('has-error');
    status.textContent = 'Saving…';
    frappe.call({
        method: NOTES_API + 'save_item_note',
        args: { item_code: code, note: value },
        callback: function (r) {
            const d = (r && r.message) || {};
            ITEM_NOTES[code] = d.note || '';
            ITEM_NOTE_META[code] = { by: d.modified_by_name || d.modified_by || '', at: d.modified || '' };
            closeNoteEditor(editor);
            refreshNoteCells(code);
            document.querySelectorAll('.note-view[data-note-item]').forEach(function (v) {
                if (v.getAttribute('data-note-item') === code) {
                    v.classList.add('note-just-saved');
                    setTimeout(function () { v.classList.remove('note-just-saved'); }, 1600);
                }
            });
        },
        error: function () {
            editor.classList.remove('is-saving');
            editor.classList.add('has-error');
            status.textContent = 'Not saved. Try again.';
            ta.focus();
        }
    });
}

