/* =============================================
   LIVE MENU — Motley Terpz (Light Theme)
   ============================================= */

@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&display=swap');

.live-menu {
    --lm-bg: #f5f5f3;
    --lm-surface: #ffffff;
    --lm-surface-hover: #f9f8f6;
    --lm-border: #e2e0db;
    --lm-text: #1a1a1a;
    --lm-text-muted: #6b6b6b;
    --lm-text-dim: #999;
    --lm-purple: #7b68ee;
    --lm-purple-light: #ebe8fd;
    --lm-purple-dark: #5a4bd1;
    --lm-gold: #d4a843;
    --lm-gold-light: #e8c56d;
    --lm-green: #2d6a4f;
    --lm-notes-bg: #fef9ef;
    --lm-notes-border: #f0d98d;
    --lm-radius: 8px;
    --lm-shadow: 0 1px 3px rgba(0,0,0,0.06);
    --lm-font: 'Outfit', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

    font-family: var(--lm-font);
    background: var(--lm-bg);
    color: var(--lm-text);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

/* ===== HEADER (dark branded) ===== */
.lm-header {
    background: linear-gradient(180deg, #1a1a2e 0%, #1e1e32 100%);
    color: white;
    padding: 2rem 1.5rem;
    text-align: center;
    position: relative;
}

.lm-header::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--lm-purple), var(--lm-gold), var(--lm-purple));
}

.lm-header-inner {
    position: relative;
    z-index: 1;
}

.lm-title {
    font-family: var(--lm-font);
    font-size: 2.2rem;
    font-weight: 800;
    margin: 0;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    background: linear-gradient(135deg, #ffffff 0%, #d4a843 60%, #e8c56d 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.lm-subtitle {
    font-size: 0.75rem;
    margin: 0.3rem 0 0;
    text-transform: uppercase;
    letter-spacing: 0.25em;
    font-weight: 500;
    color: rgba(255,255,255,0.5);
}

/* ===== BODY LAYOUT ===== */
.lm-body {
    display: flex;
    flex: 1;
    max-width: 1200px;
    width: 100%;
    margin: 0 auto;
    padding: 1.5rem;
    gap: 1.5rem;
}

/* ===== SIDEBAR ===== */
.lm-sidebar {
    width: 240px;
    flex-shrink: 0;
}

.lm-sidebar-header {
    display: none;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: var(--lm-surface);
    border: 1px solid var(--lm-border);
    border-radius: var(--lm-radius);
    cursor: pointer;
    margin-bottom: 0.5rem;
    font-weight: 600;
    font-size: 0.9rem;
}

.lm-sidebar-toggle {
    font-size: 0.7rem;
    color: var(--lm-text-muted);
}

.lm-sidebar-list {
    display: flex;
    flex-direction: column;
    gap: 4px;
    transition: max-height 0.3s ease, opacity 0.3s ease;
}

.lm-sidebar-list.collapsed {
    max-height: 0;
    overflow: hidden;
    opacity: 0;
}

.lm-nav-btn {
    display: block;
    width: 100%;
    text-align: left;
    padding: 0.75rem 1rem;
    border: 1px solid var(--lm-border);
    border-radius: var(--lm-radius);
    background: var(--lm-surface);
    color: var(--lm-text);
    font-family: var(--lm-font);
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    box-shadow: var(--lm-shadow);
}

.lm-nav-btn:hover {
    background: var(--lm-purple-light);
    border-color: var(--lm-purple);
    transform: translateX(3px);
}

.lm-nav-btn.active {
    background: var(--lm-purple);
    color: white;
    border-color: var(--lm-purple);
    box-shadow: 0 2px 8px rgba(123, 104, 238, 0.3);
    font-weight: 600;
}

/* ===== MAIN CONTENT ===== */
.lm-main {
    flex: 1;
    min-width: 0;
}

.lm-placeholder {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 300px;
    color: var(--lm-text-dim);
    text-align: center;
}

.lm-placeholder-icon {
    font-size: 2.5rem;
    margin-bottom: 1rem;
    opacity: 0.3;
}

.lm-placeholder p {
    font-size: 0.95rem;
    margin: 0;
}

.lm-loading-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 200px;
    color: var(--lm-text-muted);
    gap: 1rem;
}

.lm-spinner {
    width: 32px;
    height: 32px;
    border: 3px solid var(--lm-border);
    border-top-color: var(--lm-purple);
    border-radius: 50%;
    animation: lm-spin 0.7s linear infinite;
}

@keyframes lm-spin {
    to { transform: rotate(360deg); }
}

/* ===== GROUP HEADER ===== */
.lm-group-header {
    margin-bottom: 1.25rem;
}

.lm-group-name {
    font-family: var(--lm-font);
    font-size: 1.75rem;
    font-weight: 700;
    margin: 0 0 0.75rem 0;
    color: var(--lm-text);
}

.lm-notes-card {
    background: var(--lm-notes-bg);
    border: 1px solid var(--lm-notes-border);
    border-left: 4px solid var(--lm-gold);
    border-radius: var(--lm-radius);
    padding: 0.85rem 1rem;
    font-size: 0.85rem;
    line-height: 1.6;
    color: #5a4e2f;
}

.lm-items-count {
    font-size: 0.75rem;
    color: var(--lm-text-dim);
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    margin-bottom: 1rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid var(--lm-border);
}

/* ===== STRAIN TABLE (with qty) ===== */
.lm-strain-table {
    background: var(--lm-surface);
    border: 1px solid var(--lm-border);
    border-radius: var(--lm-radius);
    overflow: hidden;
    box-shadow: var(--lm-shadow);
}

.lm-strain-row {
    display: flex;
    align-items: center;
    padding: 0.75rem 1.25rem;
    border-bottom: 1px solid #f0eeeb;
    transition: background 0.15s ease;
}

.lm-strain-row:last-child {
    border-bottom: none;
}

.lm-strain-row:not(.lm-strain-header):hover {
    background: var(--lm-surface-hover);
}

.lm-strain-header {
    background: #f5f4f1;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--lm-text-muted);
    padding: 0.65rem 1.25rem;
}

.lm-strain-name-col {
    flex: 1;
    font-size: 0.9rem;
    font-weight: 500;
}

.lm-strain-qty-col {
    width: 90px;
    text-align: right;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--lm-green);
}

.lm-strain-header .lm-strain-qty-col {
    color: var(--lm-text-muted);
    font-weight: 700;
}

/* ===== STRAIN CHIPS (no qty) ===== */
.lm-strain-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.lm-strain-chip {
    display: inline-block;
    padding: 0.5rem 1rem;
    background: var(--lm-surface);
    border: 1px solid var(--lm-border);
    border-radius: 50px;
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--lm-text);
    box-shadow: var(--lm-shadow);
    transition: all 0.2s ease;
}

.lm-strain-chip:hover {
    border-color: var(--lm-purple);
    background: var(--lm-purple-light);
}

/* ===== EMPTY / ERROR ===== */
.lm-empty {
    text-align: center;
    padding: 2rem;
    color: var(--lm-text-dim);
    font-size: 0.9rem;
}

.lm-error {
    color: #c0392b;
}

.lm-loading {
    text-align: center;
    padding: 1.5rem;
    color: var(--lm-text-muted);
    font-size: 0.9rem;
}

/* ===== FOOTER ===== */
.lm-footer {
    text-align: center;
    padding: 1.5rem;
    border-top: 1px solid var(--lm-border);
    font-size: 0.85rem;
    color: var(--lm-text-muted);
    background: var(--lm-surface);
    margin-top: auto;
}

.lm-footer a {
    color: var(--lm-purple);
    text-decoration: none;
    font-weight: 600;
}

.lm-footer a:hover {
    text-decoration: underline;
}

/* =============================================
   RESPONSIVE
   ============================================= */

@media (max-width: 767.98px) {
    .lm-header { padding: 1.25rem 1rem; }
    .lm-title { font-size: 1.5rem; }
    .lm-body { flex-direction: column; padding: 1rem; gap: 1rem; }
    .lm-sidebar { width: 100%; }
    .lm-sidebar-header { display: flex; }
    .lm-nav-btn { padding: 0.6rem 0.85rem; font-size: 0.8rem; }
    .lm-group-name { font-size: 1.35rem; }
    .lm-strain-row { padding: 0.6rem 0.85rem; }
    .lm-strain-name-col { font-size: 0.82rem; }
    .lm-strain-qty-col { font-size: 0.78rem; width: 70px; }
    .lm-strain-chip { padding: 0.4rem 0.75rem; font-size: 0.78rem; }
    .lm-notes-card { font-size: 0.8rem; padding: 0.7rem 0.85rem; }
}

@media (max-width: 399.98px) {
    .lm-title { font-size: 1.25rem; }
    .lm-strain-chips { gap: 6px; }
    .lm-strain-chip { padding: 0.35rem 0.6rem; font-size: 0.72rem; }
}

@media (min-width: 768px) and (max-width: 991.98px) {
    .lm-sidebar { width: 200px; }
}

@media (min-width: 992px) {
    .lm-title { font-size: 2.5rem; }
    .lm-body { padding: 2rem; gap: 2rem; }
    .lm-sidebar { width: 260px; position: sticky; top: 20px; align-self: flex-start; }
}

/* ===== Scrollbar ===== */
.lm-sidebar-list::-webkit-scrollbar { width: 4px; }
.lm-sidebar-list::-webkit-scrollbar-track { background: transparent; }
.lm-sidebar-list::-webkit-scrollbar-thumb { background: #ccc; border-radius: 2px; }

