frappe.ready(function () {
    loadLiveMenuGroups();
});

/* ──────────────────────────────────────
   State
   ────────────────────────────────────── */
let activeGroup = null;

/* ──────────────────────────────────────
   Menu Mode (set in HTML via window.LIVE_MENU_MODE)
   'extracts'     → hide Fresh Frozen
   'fresh_frozen'  → show only Fresh Frozen
   undefined       → show all
   ────────────────────────────────────── */
function filterGroupsByMode(groups) {
    let mode = (window.LIVE_MENU_MODE || '').toLowerCase();
    if (mode === 'extracts') {
        return groups.filter(function (g) {
            return g.name.toLowerCase().indexOf('fresh frozen') !== 0;
        });
    }
    if (mode === 'fresh_frozen') {
        return groups.filter(function (g) {
            return g.name.toLowerCase() === 'fresh frozen';
        });
    }
    return groups;
}

/* ──────────────────────────────────────
   Client-side display name overrides
   ────────────────────────────────────── */
const DISPLAY_NAMES = {
    'vrr': 'Vape Ready Rosin',
    'liquid live resin': 'Liquid Live Resin',
    'distallate': 'Distillate',
};

function getDisplayName(groupName) {
    return DISPLAY_NAMES[groupName.toLowerCase()] || groupName;
}

/* Only Fresh Frozen shows qty to clients */
function shouldShowQty(groupName) {
    return groupName.toLowerCase() === 'fresh frozen';
}

/* ──────────────────────────────────────
   Group Merging & Source Mapping
   ────────────────────────────────────── */

/* Groups hidden from sidebar (merged into another group) */
const HIDDEN_GROUPS = [];

/* When fetching a group, also fetch items from these additional groups */
const MERGE_GROUPS = {};

/* Override the actual item group to fetch from backend */
const SOURCE_GROUP_MAP = {};

/* Client-side note overrides (appended to backend notes) */
const CLIENT_NOTES = {
    '1g o2 vapes': 'Available in Liquid Live Resin or Vape Ready Rosin',
};

function getSourceGroup(groupName) {
    return SOURCE_GROUP_MAP[groupName.toLowerCase()] || groupName;
}

/* ──────────────────────────────────────
   Load Item Groups (ordered by custom_sequence_number)
   ────────────────────────────────────── */
function loadLiveMenuGroups() {
    frappe.call({
        method: 'cannabis_management.api.live_menu.get_live_menu_groups',
        async: true,
        callback: function (r) {
            if (r.message && r.message.length) {
                let filtered = filterGroupsByMode(r.message);

                // Remove groups that are merged into other groups
                filtered = filtered.filter(function (g) {
                    return HIDDEN_GROUPS.indexOf(g.name.toLowerCase()) === -1;
                });

                // Motley Terpz: pin these groups to the top of the sidebar, in this order.
                var TOP_PRIORITY = ['tier 1 plus', 'tier 1', 'tier 2', 'tier 3'];
                filtered.sort(function (a, b) {
                    var ai = TOP_PRIORITY.indexOf(a.name.toLowerCase());
                    var bi = TOP_PRIORITY.indexOf(b.name.toLowerCase());
                    if (ai === -1) ai = TOP_PRIORITY.length;
                    if (bi === -1) bi = TOP_PRIORITY.length;
                    return ai - bi;
                });

                if (filtered.length) {
                    renderGroupNav(filtered);
                    selectGroup(filtered[0].name, filtered[0]);
                } else {
                    document.getElementById('lm-group-list').innerHTML =
                        '<div class="lm-empty">No categories available</div>';
                }
            } else {
                document.getElementById('lm-group-list').innerHTML =
                    '<div class="lm-empty">No categories available</div>';
            }
        },
        error: function () {
            document.getElementById('lm-group-list').innerHTML =
                '<div class="lm-empty lm-error">Failed to load menu</div>';
        }
    });
}

/* ──────────────────────────────────────
   Render Sidebar Navigation
   ────────────────────────────────────── */
function renderGroupNav(groups) {
    let html = '';
    groups.forEach(function (g) {
        let label = getDisplayName(g.name);
        let escapedName = g.name.replace(/'/g, "\\'");
        html += '<button class="lm-nav-btn" data-group="' + g.name + '" '
            + 'onclick="selectGroup(\'' + escapedName + '\')">'
            + label
            + '</button>';
    });
    document.getElementById('lm-group-list').innerHTML = html;
}

/* ──────────────────────────────────────
   Fetch helper (wraps frappe.call in a Promise)
   ────────────────────────────────────── */
function fetchGroupItems(itemGroup) {
    return new Promise(function (resolve) {
        frappe.call({
            method: 'cannabis_management.api.live_menu.get_live_menu_items',
            args: { item_group: itemGroup },
            async: true,
            callback: function (r) {
                resolve(r.message || { items: [], notes: '', group_name: itemGroup });
            },
            error: function () {
                resolve({ items: [], notes: '', group_name: itemGroup });
            }
        });
    });
}

/* ──────────────────────────────────────
   Select a Group
   ────────────────────────────────────── */
function selectGroup(groupName, groupData) {
    activeGroup = groupName;

    // Update active button
    document.querySelectorAll('.lm-nav-btn').forEach(function (btn) {
        btn.classList.toggle('active', btn.getAttribute('data-group') === groupName);
    });

    // Collapse sidebar on mobile
    if (window.innerWidth < 768) {
        document.querySelector('.lm-sidebar-list').classList.add('collapsed');
        document.getElementById('sidebar-toggle').innerHTML = '&#9660;';
    }

    // Show loading
    document.getElementById('lm-placeholder').style.display = 'none';
    document.getElementById('lm-content').style.display = 'none';
    document.getElementById('lm-loading').style.display = 'flex';

    // Build list of groups to fetch
    var key = groupName.toLowerCase();
    var groupsToFetch = [getSourceGroup(groupName)];
    if (MERGE_GROUPS[key]) {
        MERGE_GROUPS[key].forEach(function (extra) {
            groupsToFetch.push(getSourceGroup(extra));
        });
    }

    // Fetch all groups in parallel and merge results
    Promise.all(groupsToFetch.map(fetchGroupItems)).then(function (results) {
        var mergedItems = [];
        var notesParts = [];

        results.forEach(function (r) {
            if (r && r.items) mergedItems = mergedItems.concat(r.items);
            if (r && r.notes) notesParts.push(r.notes);
        });

        // Append client-side notes if configured
        var clientNote = CLIENT_NOTES[key] || '';
        if (clientNote) notesParts.push(clientNote);

        // Deduplicate by item_code
        var seen = {};
        mergedItems = mergedItems.filter(function (item) {
            if (seen[item.item_code]) return false;
            seen[item.item_code] = true;
            return true;
        });

        // Sort alphabetically by item_name
        mergedItems.sort(function (a, b) {
            return (a.item_name || '').localeCompare(b.item_name || '');
        });

        renderLiveMenu({
            items: mergedItems,
            notes: notesParts.join('\n'),
            group_name: groupName,
        });
    }).catch(function () {
        document.getElementById('lm-loading').style.display = 'none';
        document.getElementById('lm-content').style.display = 'block';
        document.getElementById('lm-items-grid').innerHTML =
            '<div class="lm-empty lm-error">Error loading data. Please try again.</div>';
    });
}

/* ──────────────────────────────────────
   Clean Item Name (remove suffixes like _H, _CDC, _X-GroupName)
   ────────────────────────────────────── */
function cleanStrainName(itemName, itemGroup) {
    if (!itemName) return '—';

    let name = itemName;

    // Remove everything after the last " - " or " – " (catches LLR, O2 Vape, Fresh Frozen, etc.)
    name = name.replace(/\s*[-–]\s*[^-–]+$/, '');

    // Remove "_X-<anything>" patterns (e.g. "_1-Fresh Frozen", "_G-Primes")
    name = name.replace(/[_][A-Za-z0-9][-].+$/, '');

    // Remove trailing "_CDC"
    name = name.replace(/_CDC$/i, '');

    // Remove trailing "_H"
    name = name.replace(/_H$/i, '');

    // Remove trailing "_X" where X is a single letter or digit
    name = name.replace(/_[A-Za-z0-9]$/, '');

    // Replace underscores with spaces
    name = name.replace(/_/g, ' ');

    return name.trim() || itemName;
}

/* ──────────────────────────────────────
   Render Live Menu Content
   ────────────────────────────────────── */
function renderLiveMenu(data) {
    let items = data.items || [];
    let showQty = shouldShowQty(data.group_name);
    let notes = data.notes || '';
    let displayName = getDisplayName(data.group_name);
    let groupName = data.group_name;

    // Hide loading, show content
    document.getElementById('lm-loading').style.display = 'none';
    document.getElementById('lm-content').style.display = 'block';

    // Group header
    document.getElementById('lm-group-name').innerText = displayName;

    // Notes
    let notesEl = document.getElementById('lm-group-notes');
    if (notes) {
        notesEl.innerHTML = '<div class="lm-notes-card">' + formatNotes(notes) + '</div>';
        notesEl.style.display = 'block';
    } else {
        notesEl.style.display = 'none';
    }

    // Items count
    document.getElementById('lm-items-count').innerText =
        items.length + ' strain' + (items.length !== 1 ? 's' : '') + ' available';

    // Items grid
    if (!items.length) {
        document.getElementById('lm-items-grid').innerHTML =
            '<div class="lm-empty">No strains currently available in this category.</div>';
        return;
    }

    let html = '<div class="lm-strain-list">';

    if (showQty) {
        // Table layout with quantity
        html += '<div class="lm-strain-table">';
        html += '<div class="lm-strain-row lm-strain-header">';
        html += '<span class="lm-strain-name-col">Strain</span>';
        html += '<span class="lm-strain-qty-col">Qty</span>';
        html += '</div>';

        items.forEach(function (item) {
            let cleanName = cleanStrainName(item.item_name, groupName);
            let qty = parseFloat(item.available_qty || 0);
            let qtyDisplay = formatQty(qty);

            html += '<div class="lm-strain-row">';
            html += '<span class="lm-strain-name-col">' + cleanName + '</span>';
            html += '<span class="lm-strain-qty-col">' + qtyDisplay + '</span>';
            html += '</div>';
        });

        html += '</div>';
    } else {
        // Simple list — no quantity
        html += '<div class="lm-strain-chips">';
        items.forEach(function (item) {
            let cleanName = cleanStrainName(item.item_name, groupName);
            html += '<span class="lm-strain-chip">' + cleanName + '</span>';
        });
        html += '</div>';
    }

    html += '</div>';
    document.getElementById('lm-items-grid').innerHTML = html;
}

/* ──────────────────────────────────────
   Helpers
   ────────────────────────────────────── */
function formatQty(qty) {
    if (qty >= 1) {
        return parseFloat(qty.toFixed(1)) + ' lbs';
    }
    // Convert to grams (1 lb = 453.592 g) — or just show as-is
    return parseFloat(qty.toFixed(2));
}

function formatNotes(text) {
    // Simple: replace newlines with <br>
    return text.replace(/\n/g, '<br>');
}

/* ──────────────────────────────────────
   Sidebar Toggle (Mobile)
   ────────────────────────────────────── */
function toggleMenuSidebar() {
    if (window.innerWidth < 768) {
        let list = document.querySelector('.lm-sidebar-list');
        let icon = document.getElementById('sidebar-toggle');
        list.classList.toggle('collapsed');
        icon.innerHTML = list.classList.contains('collapsed') ? '&#9660;' : '&#9650;';
    }
}
